# Define the compliance wrapper with specific settings
compliance_wrapper = AirLangchainTrust(
    audit_hmac_secret="super_secret_audit_key",

    consent_mode="BLOCK_HIGH_AND_CRITICAL",
    vault_patterns=["email", "ssn", "credit_card"],
