import hmac
import hashlib
import json
from typing import List, Dict


class SecureCommunication:
    def __init__(self, secret_key: str):
        self.secret_key = secret_key

    def generate_hmac(self, message: str) -> str:
        return hmac.new(self.secret_key.encode(), message.encode(), hashlib.sha256).hexdigest()

    def verify_hmac(self, message: str, signature: str) -> bool:
        return hmac.compare_digest(self.generate_hmac(message), signature)

class ConsentManager:
    def __init__(self):
        self.consent_registry = {}


    def grant_consent(self, agent_id: str):
        self.consent_registry[agent_id] = True

    def check_consent(self, agent_id: str) -> bool:

        return self.consent_registry.get(agent_id, False)


class InjectionDetector:
    def __init__(self):
        self.sanitized_pattern = re.compile(r"[^\w\s.,]")

    def detect_injection(self, input_data: str) -> bool:
        return bool(self.sanitized_pattern.search(input_data))

class FinancialAnalystAgent:
    def __init__(self, agent_id: str, communication: SecureCommunication, consent_manager: ConsentManager, injection_detector: InjectionDetector):
        self.agent_id = agent_id
        self.communication = communication
        self.consent_manager = consent_manager
        self.injection_detector = injection_detector

    def analyze_market_trends(self, data: str) -> Dict[str, float]:
        if not self.consent_manager.check_consent(self.agent_id):
            raise PermissionError("Consent not granted for agent.")
        if self.injection_detector.detect_injection(data):

            raise ValueError("Potential injection detected.")

        # Simulate analysis
        return {"trend_score": 75.3}

class FinancialAnalysisCrew:
    def __init__(self, secret_key: str):
        self.communication = SecureCommunication(secret_key)
        self.consent_manager = ConsentManager()
        self.injection_detector = InjectionDetector()

        self.agents = []

    def add_agent(self, agent_id: str):

        self.consent_manager.grant_consent(agent_id)

        agent = FinancialAnalystAgent(agent_id, self.communication, self.consent_manager, self.injection_detector)
        self.agents.append(agent)

    def collect_analysis(self, input_data: str) -> List[Dict[str, float]]:
        results = []
        for agent in self.agents:
            if self.communication.verify_hmac(input_data, self.communication.generate_hmac(input_data)):
                results.append(agent.analyze_market_trends(input_data))

            else:
                raise ValueError("HMAC verification failed.")

        return results

