from langchain.agents import initialize_agent, AgentType

from langchain.prompts import ChatPromptTemplate
from langchain.llms import GPT3Turbo
from langchain.tools import Tool
from langchain.chains import LLMChain

class PerformanceTracker:
    def __init__(self):
        self.student_scores = {}


    def update_score(self, student_id, score):
        self.student_scores[student_id] = score


    def get_score(self, student_id):
        return self.student_scores.get(student_id, 0)

performance_tracker = PerformanceTracker()


class MathTutorTool:
    def __call__(self, query):

        # Simulated response from a math tutoring tool
        if "solve" in query:
            return "Let's work through this problem together."
        return "Please provide a math problem to solve."

class ScienceTutorTool:
    def __call__(self, query):
        # Simulated response from a science tutoring tool
        if "explain" in query:
            return "Here's a detailed explanation of the concept."
        return "Please provide a topic you'd like to learn about."

math_tool = Tool(name="MathAssistant", func=MathTutorTool(), description="Helps solve math problems.")
science_tool = Tool(name="ScienceAssistant", func=ScienceTutorTool(), description="Provides science explanations.")

llm = GPT3Turbo()

adapt_prompt = ChatPromptTemplate.from_template(
    "Student performance is {student_performance}. Use this information to adjust tutoring methods."
)

llm_chain = LLMChain(llm=llm, prompt=adapt_prompt)

tutoring_agent = initialize_agent(
    tools=[math_tool, science_tool],
    llm=llm,
    agent_type=AgentType.CHAT_CONVERSATIONAL_REACT_DESCRIPTION,
    verbose=False
)

def adapt_tutoring(student_id, query):
    current_score = performance_tracker.get_score(student_id)
    student_performance = "excellent" if current_score > 80 else "needs improvement"

    adapted_response = llm_chain.run(student_performance=student_performance)
    tool_response = tutoring_agent.run(query)

    return f"{adapted_response}\n\n{tool_response}"

