from crewai_system import CrewAI
from aircrewaitrust_guard import AirCrewaiTrust

class CrewAISystem:
    def __init__(self):
        self.crew = CrewAI()
        self.trust_guard = AirCrewaiTrust(
            allowed_tools=["NavigatorAI", "FuelOptimizer"],
            model_versions=["aviator-v1.0"],
            business_contexts=["commercial_airliner"]
        )

    def execute(self, command):
        if self.trust_guard.validate(command):
            return self.crew.perform(command)
        else:
            raise PermissionError("Command not compliant with AirCrewaiTrust policies.")

