# Define another custom tool
class ScienceAssessmentTool(Tool):

    def __init__(self):
        super().__init__(name="ScienceAssessment", description="Assesses student's science understanding")

    def execute(self, data):

        # Mock assessment logic
        return {"score": 78, "feedback": "Good understanding of physics, weak in biology"}

# Set up the tool box
tool_box = ToolBox(tools=[MathAssessmentTool(), ScienceAssessmentTool()])

