from ai_toolkit_v2 import Agent, Task, System

# Define the roles
class Researcher(Agent):
    def __init__(self, name):
        super().__init__(name)

    def perform_task(self, task: Task):
        logger.info(f"{self.name} is conducting research on {task.description}.")
        data = f"Research data on {task.description}"
        return data

class Writer(Agent):
    def __init__(self, name):
        super().__init__(name)

    def perform_task(self, task: Task, research_data):
        logger.info(f"{self.name} is writing based on the research data.")
        content = f"Written content based on {research_data}"
        return content

class Reviewer(Agent):
    def __init__(self, name):
        super().__init__(name)

    def perform_task(self, task: Task, content):
        logger.info(f"{self.name} is reviewing the written content.")
        review_notes = f"Review notes for: {content}"
        return review_notes

# Create the system with agents
class CrewSystem(System):
    def __init__(self, task_description):
        self.researcher = Researcher("Alice")
        self.writer = Writer("Bob")
        self.reviewer = Reviewer("Charlie")
        self.task = Task(description=task_description)

    def execute(self):
        research_data = self.researcher.perform_task(self.task)
        content = self.writer.perform_task(self.task, research_data)
        review_notes = self.reviewer.perform_task(self.task, content)
        logger.info(f"Review notes: {review_notes}")

