from langchain.embeddings import Embeddings

class ProductDescriptionAnalyzer:
    def __init__(self, embedding_model='text-embedding-ada-002'):
        self.embedding_model = embedding_model
        self.embedder = Embeddings(model=self.embedding_model)

    def get_embedding(self, description: str):
        return self.embedder.embed([description])[0]

    def compare_similarity(self, desc1: str, desc2: str):
        embed1 = self.get_embedding(desc1)
        embed2 = self.get_embedding(desc2)
        return self.compute_cosine_similarity(embed1, embed2)

    @staticmethod
    def compute_cosine_similarity(embedding1, embedding2):
        import numpy as np
        embedding1 = np.array(embedding1)
        embedding2 = np.array(embedding2)
        dot_product = np.dot(embedding1, embedding2)
        norm_a = np.linalg.norm(embedding1)
        norm_b = np.linalg.norm(embedding2)
        return dot_product / (norm_a * norm_b)


# Example usage:
