    analyzer = ProductDescriptionAnalyzer()
    description_a = "This is a state-of-the-art smart speaker with voice control."
    description_b = "Experience superior sound quality with this wireless smart speaker."
    similarity_score = analyzer.compare_similarity(description_a, description_b)
