                    format='%(asctime)s - %(levelname)s - %(message)s')

class ConsentManager:
    def __init__(self):

        self.consent_map = {}

    def give_consent(self, user_id: str):
        self.consent_map[user_id] = True
        logging.info(f"Consent granted for user: {user_id}")

    def revoke_consent(self, user_id: str):
        self.consent_map[user_id] = False
        logging.info(f"Consent revoked for user: {user_id}")

    def has_consent(self, user_id: str) -> bool:
        return self.consent_map.get(user_id, False)

class InjectionDetector:
    def detect_injection(self, input_data: str) -> bool:
        # Simple heuristic check for SQL-like injection patterns
        if any(keyword in input_data for keyword in ["SELECT", "DROP", "--", ";"]):
            logging.warning(f"Injection detected in input: {input_data}")
            return True
        return False

class FinancialCrewAI:
    def __init__(self, consent_manager: ConsentManager, injection_detector: InjectionDetector):
        self.consent_manager = consent_manager

        self.injection_detector = injection_detector


    def process_request(self, user_id: str, request_data: str) -> Dict[str, Any]:
        if not self.consent_manager.has_consent(user_id):
            logging.error(f"Consent not given for user: {user_id}")
            return {"status": "error", "message": "Consent not given"}

        if self.injection_detector.detect_injection(request_data):

            return {"status": "error", "message": "Injection detected"}


        # Simulate financial analysis
        analysis_result = {"status": "success", "analysis": f"Processed data for {user_id}"}
        logging.info(f"Request processed for user: {user_id} with data: {request_data}")
        return analysis_result


def create_hmac(token: str, secret_key: str) -> str:
    return hmac.new(secret_key.encode(), token.encode(), hashlib.sha256).hexdigest()

