import re
from typing import List, Dict

class ResumeAnalyzer:
    def __init__(self, model_version: str = "model_v3.5"):
        self.model_version = model_version
        self.required_skills = ["Python", "Data Analysis", "Machine Learning"]

    def parse_resume(self, resume_text: str) -> Dict[str, int]:
        word_list = re.findall(r'\b\w+\b', resume_text.lower())

        word_freq = {}
        for word in word_list:
            if word in word_freq:
                word_freq[word] += 1
            else:
                word_freq[word] = 1
        return word_freq

    def score_candidate(self, word_freq: Dict[str, int]) -> float:
        score = 0
        for skill in self.required_skills:
            score += word_freq.get(skill.lower(), 0)
        return score

    def evaluate_resumes(self, resumes: List[str]) -> List[float]:
        scores = []
        for resume in resumes:
            word_freq = self.parse_resume(resume)
            candidate_score = self.score_candidate(word_freq)
            scores.append(candidate_score)
        return scores

# Example Usage
resumes = [
    "Expert in Python and Machine Learning. Experience with Data Analysis.",

    "Skilled in Java and Web Development. Basic knowledge of Python."
]

analyzer = ResumeAnalyzer()
scores = analyzer.evaluate_resumes(resumes)
print(scores)

from crewai import MultiAgentSystem, Agent, Task, Message

class ResearchAgent(Agent):
    def __init__(self):
        super().__init__('Researcher')

    def execute_task(self, task: Task):

        if task.description == 'Research Topic':
            findings = self.gather_data(task.parameters)
            self.send_message('Writer', Message('Findings', findings))


    def gather_data(self, topic):
        # Simulate data gathering
        return f"Data on {topic} collected from various sources."

class WritingAgent(Agent):
    def __init__(self):

        super().__init__('Writer')

    def execute_task(self, task: Task):
        if task.description == 'Compose Article':
            article = self.create_content(task.parameters)
            self.send_message('Reviewer', Message('Draft', article))

    def create_content(self, findings):
        # Simulate article writing
        return f"Article based on findings: {findings}"

class ReviewAgent(Agent):
    def __init__(self):
        super().__init__('Reviewer')

    def execute_task(self, task: Task):
        if task.description == 'Review Draft':
            reviewed_article = self.review_content(task.parameters)
            self.send_message('Project Manager', Message('Reviewed Article', reviewed_article))


    def review_content(self, draft):
        # Simulate content review
        return f"Reviewed and approved version of: {draft}"

# Define the multi-agent system

class PublishingSystem(MultiAgentSystem):

    def __init__(self):
        super().__init__()
        self.add_agent(ResearchAgent())

        self.add_agent(WritingAgent())
        self.add_agent(ReviewAgent())

    def start_publishing_process(self, topic):
        self.send_message('Researcher', Message('Task', Task('Research Topic', topic)))

# Usage
if __name__ == "__main__":
    system = PublishingSystem()
    system.start_publishing_process('Artificial Intelligence in Healthcare')

import asyncio
import logging
import json
import os
from datetime import datetime
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,

    PermissionResultAllow, PermissionResultDeny,

)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
os.makedirs("./audit", exist_ok=True)

DANGEROUS_COMMANDS = ["rm -rf", "sudo", "chmod 777", "mkfs"]

async def block_dangerous_bash(input_data, tool_use_id, context):
    """Block dangerous bash commands."""
    if input_data.get("tool_name") == "Bash":
        cmd = input_data.get("tool_input", {{}}).get("command", "")
        for pattern in DANGEROUS_COMMANDS:
            if pattern in cmd:
                logger.warning(f"Blocked dangerous command: {{cmd}}")
                return {{
                    "hookSpecificOutput": {{
                        "hookEventName": "PreToolUse",
                        "permissionDecision": "deny",
                        "permissionDecisionReason": f"Dangerous: {{pattern}}",
                    }}
                }}

    return {{}}

async def audit_log(input_data, tool_use_id, context):
    """Log every action result to audit directory."""
    record = {{
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "action": input_data.get("tool_name"),
        "tool_use_id": tool_use_id,
    }}
    fname = f"./audit/{{tool_use_id or 'unknown'}}.json"
    with open(fname, "w") as f:
        json.dump(record, f)
    return {{}}

async def permission_handler(tool_name, input_data, context):
    """Risk-based permission handler."""
    if tool_name == "Bash":

        cmd = input_data.get("command", "")
        if any(p in cmd for p in DANGEROUS_COMMANDS):
            return PermissionResultDeny(message="Blocked by policy")
    return PermissionResultAllow(updated_input=input_data)

async def main():
    options = ClaudeAgentOptions(
        allowed_tools=["Read", "Write", "Bash"],

        can_use_tool=permission_handler,
        max_turns=10,
        hooks={{
            "PreToolUse": [

                HookMatcher(matcher="Bash", hooks=[block_dangerous_bash]),
            ],
            "PostToolUse": [HookMatcher(hooks=[audit_log])],
        }},
    )

    async with ClaudeSDKClient(options=options) as client:
        await client.query("Find the latest EU AI regulation news")
        async for message in client.receive_response():
            print(message)

asyncio.run(main())

