from crewai import Crew, Agent

class ResearchAgent(Agent):
    def define_role(self):
        return {
            "name": "Research Specialist",
            "description": "Collects and synthesizes information relevant to the project tasks."
        }

    def perform_task(self, task):
        # Simulate research task processing
        data_sources = ["https://api.example.com/data", "https://api.anotherexample.com/info"]
        research_data = {url: f"Data from {url}" for url in data_sources}
        return research_data

class WritingAgent(Agent):
    def define_role(self):
        return {
            "name": "Content Creator",
            "description": "Generates written content based on the researched data."
        }

    def perform_task(self, task):
        # Simulate writing task based on research
        research_data = task.get('research_data', {})
        content = " ".join(f"Written paragraph based on {data}" for data in research_data.values())
        return content

class ReviewAgent(Agent):
    def define_role(self):
        return {
            "name": "Quality Reviewer",
            "description": "Evaluates and provides feedback on the content for quality assurance."
        }

    def perform_task(self, task):
        # Simulate review process
        content = task.get('content', "")
        feedback = "Looks good!" if len(content) > 20 else "Needs more content."
        return feedback

class ReportGenerationSystem(Crew):
    def __init__(self):
        super().__init__(name="Report Generation System")
        self.add_agent(ResearchAgent())
        self.add_agent(WritingAgent())
        self.add_agent(ReviewAgent())

    def execute(self):
        # Define task pipeline
        research_task = self.create_task("Conduct Research")
        research_results = self.assign_task(research_task, "Research Specialist")

        writing_task = self.create_task("Create Content", research_data=research_results)
        written_content = self.assign_task(writing_task, "Content Creator")

        review_task = self.create_task("Review Content", content=written_content)
        review_feedback = self.assign_task(review_task, "Quality Reviewer")

        return {
            "content": written_content,
            "feedback": review_feedback
        }

# Instantiate and run the system
report_system = ReportGenerationSystem()
final_results = report_system.execute()
logger.info(final_results)

