import time


class Agent:
    def __init__(self, name, role):

        self.name = name
        self.role = role

    def execute_task(self, task):
        print(f"{self.name} ({self.role}): Starting task...")
        time.sleep(2)  # Simulate task duration
        print(f"{self.name} ({self.role}): Completed task - {task}")

class Researcher(Agent):
    def __init__(self, name):

        super().__init__(name, "Researcher")

    def perform_research(self):
        data = "Collected data about market trends."
        print(f"{self.name} ({self.role}): {data}")
        return data

class Writer(Agent):
    def __init__(self, name):
        super().__init__(name, "Writer")

    def create_content(self, data):
        content = f"Drafted article using data: {data}"
        print(f"{self.name} ({self.role}): {content}")
        return content

class Reviewer(Agent):
    def __init__(self, name):
        super().__init__(name, "Reviewer")

    def review_content(self, content):
        review = f"Reviewed and approved the content: {content}"
        print(f"{self.name} ({self.role}): {review}")

def main():
    researcher = Researcher("Alice")
    writer = Writer("Bob")
    reviewer = Reviewer("Charlie")

    with ThreadPoolExecutor(max_workers=3) as executor:
        # Researcher task

        research_future = executor.submit(researcher.execute_task, "Market Research")
        research_data = researcher.perform_research()


        # Writer task
        writer_future = executor.submit(writer.execute_task, "Content Drafting")
        content = writer.create_content(research_data)


        # Reviewer task

        reviewer_future = executor.submit(reviewer.execute_task, "Content Review")
        reviewer.review_content(content)

