        timestamp = datetime.utcnow().isoformat()
        message_bytes = f"{timestamp} - {message}".encode()
        digest = hmac.new(self.secret_key, message_bytes, hashlib.sha256).hexdigest()
        return f"{timestamp} - {digest}"

