# HMAC logging function
def log_with_hmac(message: str):
    digest = hmac.new(SECRET_KEY, message.encode(), hashlib.sha256).hexdigest()
    logging.info(f"{message} | HMAC: {digest}")

# Consent gating function
def consent_required(func):
    def wrapper(*args, **kwargs):
        consent = kwargs.get('consent', False)
        if not consent:
            raise PermissionError("Consent not provided for data processing.")
        return func(*args, **kwargs)
    return wrapper

# Injection detection function
def detect_injection(data: Dict[str, Any]) -> bool:
    # Simple injection detection logic
    for value in data.values():
        if isinstance(value, str) and ("DROP" in value.upper() or "DELETE" in value.upper()):
            return True
    return False

class FinancialCrew:
    def __init__(self):
        self.portfolio_ai = PortfolioAnalysisAI()
        self.market_trend_ai = MarketTrendAI()

    @consent_required
    def perform_analysis(self, portfolio_data: Dict[str, Any], consent: bool) -> Dict[str, Any]:
        if detect_injection(portfolio_data):
            log_with_hmac("Injection detected in input data. Aborting analysis.")
            raise ValueError("Potential injection attack detected.")

        log_with_hmac("Starting portfolio analysis.")
        portfolio_result = self.portfolio_ai.analyze_portfolio(portfolio_data)

        log_with_hmac("Predicting market trends.")
        market_result = self.market_trend_ai.predict_market_trend(portfolio_data)

        combined_results = {**portfolio_result, **market_result}
        log_with_hmac(f"Analysis complete. Results: {combined_results}")

        return combined_results

