        self.llm = LLM(api_key=api_key, model=model_version)
        self.patient_db = patient_db

    def retrieve_patient_info(self, patient_id: str) -> Dict:
        return self.patient_db.get(patient_id, {})

    def query_medical_info(self, query: str) -> str:
        result = self.llm.generate(
            instruction=query,
            max_tokens=200
        )
        return result['text']

    def run_agent(self, patient_id: str, question: str) -> str:
        patient_info = self.retrieve_patient_info(patient_id)
        if not patient_info:
            return "Patient record not found."

        context = f"Patient Information: {patient_info}.\nQuestion: {question}"
        answer = self.query_medical_info(context)
        return answer

