class AuditHandler(BaseCallbackHandler):
    """Callback processor that logs all LLM interactions."""

    def on_llm_start(self, serialized, prompts, **kwargs):
        logger.info(f"LLM call: model={{serialized.get('kwargs', {{}}).get('model', 'unknown')}}")
        for instruction in prompts:
            if any(word in instruction.lower() for word in ["ignore previous", "system instruction:"]):
                logger.warning(f"Possible injection detected in instruction")

    def on_llm_end(self, response, **kwargs):
        logger.info(f"LLM response received")

    def on_tool_start(self, serialized, input_str, **kwargs):
        logger.info(f"Tool: {{serialized.get('name')}} input={{input_str[:100]}}")

def check_rate_limit():
    global _call_count, _last_reset
    if time.time() - _last_reset > 60:
        _call_count = 0
