# Example 5: Transaction Data Handling

def validate_transaction(transaction):
    required_fields = ['amount', 'currency']
    return all(field in transaction for field in required_fields)


def anonymize_data(transaction):
    keys_to_anonymize = ['account_number', 'routing_number']
    return {k: (v if k not in keys_to_anonymize else None) for k, v in transaction.items()}

def check_currency_bias(transactions):
    return len(set(t['currency'] for t in transactions)) > 1


def handle_transactions(transactions):

    if not check_currency_bias(transactions):
        raise ValueError("Currency bias detected")
    for transaction in transactions:
        if not validate_transaction(transaction):
            raise ValueError("Invalid transaction data")
        anonymized_transaction = anonymize_data(transaction)
    return transactions

