from crewai import CrewSystem, Agent, Task
from langchain import GPT4Model, BERTModel, RobertaModel

class ResearcherAgent(Agent):
    def init_role(self):
        self.role_name = "Researcher"
        self.model = GPT4Model(version="4.1")

    def perform_task(self, data):
        research_topic = data.get("topic", "undefined")
        research_papers = self.model.generate(
            instruction=f"Conduct research on {research_topic} and summarize findings.",
            max_tokens=300
        )
        return {"research_summary": research_papers}

class WriterAgent(Agent):
    def init_role(self):
        self.role_name = "Writer"
        self.model = BERTModel(version="3.5")

    def perform_task(self, data):
        research_summary = data.get("research_summary", "")
        article = self.model.generate(
            instruction=f"Write a comprehensive article based on the following research: {research_summary}",
            max_tokens=500
        )
        return {"article_content": article}

class ReviewerAgent(Agent):
    def init_role(self):
        self.role_name = "Reviewer"
        self.model = RobertaModel(version="2.0")

    def perform_task(self, data):
        article_content = data.get("article_content", "")
        feedback = self.model.generate(
            instruction=f"Review the following article for clarity, grammar, and accuracy: {article_content}",
            max_tokens=100
        )
        return {"review_feedback": feedback}

class ContentCreationTask(Task):
    def __init__(self, topic):
        super().__init__()
        self.data = {"topic": topic}

    def execute(self, agents):
        researcher = agents["Researcher"]
        writer = agents["Writer"]
        reviewer = agents["Reviewer"]

        research_results = researcher.perform_task(self.data)
        article = writer.perform_task(research_results)
        review = reviewer.perform_task(article)

        return {"article": article["article_content"], "feedback": review["review_feedback"]}

crew_system = CrewSystem(
    agents=[
        ResearcherAgent(),
        WriterAgent(),
        ReviewerAgent()
    ]
)

task = ContentCreationTask(topic="The impact of AI on healthcare")
result = crew_system.execute_task(task)
print("Article Content:\n", result["article"])
print("\nReview Feedback:\n", result["feedback"])

