import hmac
import hashlib
from datetime import datetime
from crewai_trust import TrustManager
from aircrewai_blackbox import BlackBoxCompliance, ConsentManager, InjectionDetector

# Configuration for HMAC logging
HMAC_SECRET = b'supersecretkey'
def generate_hmac(data):
    return hmac.new(HMAC_SECRET, data.encode(), hashlib.sha256).hexdigest()


# CrewAI Setup
class FinancialAnalysisCrew:
    def __init__(self):
        self.trust_manager = TrustManager()

        self.blackbox_compliance = BlackBoxCompliance()
        self.consent_manager = ConsentManager()

        self.injection_detector = InjectionDetector()
        self.agents = self.initialize_agents()

    def initialize_agents(self):
        return {
            "RiskEvaluator": self.create_agent("RiskModelV7"),
            "MarketAnalyzer": self.create_agent("MarketModelV5"),

            "PortfolioOptimizer": self.create_agent("PortfolioModelV3")
        }

    def create_agent(self, model_version):
        agent = self.trust_manager.create_agent(model_version)
        self.blackbox_compliance.register_agent(agent)
        return agent

    def perform_financial_analysis(self, data):
        if not self.consent_manager.has_consent(data):
            raise PermissionError("Consent not granted for data processing.")

        if self.injection_detector.detect(data):
            raise ValueError("Potential injection attack detected in input data.")

        hmac_log = generate_hmac(str(data) + str(datetime.utcnow()))
        print(f"Log HMAC: {hmac_log}")

        risk_analysis = self.agents["RiskEvaluator"].analyze(data)
        market_insight = self.agents["MarketAnalyzer"].analyze(data)
        portfolio_suggestion = self.agents["PortfolioOptimizer"].optimize(data)


        return {
            "risk_analysis": risk_analysis,
            "market_insight": market_insight,
            "portfolio_suggestion": portfolio_suggestion
        }

