from autogen import AssistantAgent, UserProxyAgent, run_conversation
from autogen.models import ModelV2


class DataAnalyzerAssistant(AssistantAgent):
    def __init__(self):
        super().__init__(
            name="DataAnalyzerAssistant",
            model=ModelV2("analyst-v2.1"),
            tools=["StatisticsTool", "ChartTool"]
        )


    def analyze_data(self, data):
        summary = self.call_tool("StatisticsTool", data)
        chart = self.call_tool("ChartTool", data)
        return summary, chart

class BusinessUserProxy(UserProxyAgent):
    def __init__(self):
        super().__init__(
            name="BusinessUserProxy",
            model=ModelV2("user-simulator-v2.1"),
            tools=["DataFetcherTool"]
        )

    def provide_data(self, context):

        data = self.call_tool("DataFetcherTool", context)
        return data

def main():
    assistant = DataAnalyzerAssistant()
    user_proxy = BusinessUserProxy()

    def conversation():
        context = "financial quarter analysis"
        data = user_proxy.provide_data(context)
        summary, chart = assistant.analyze_data(data)
        print("Analysis Summary:", summary)
        print("Generated Chart:", chart)

    run_conversation(conversation)

if __name__ == "__main__":
    main()

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from langchain import LangChainAgent, Tool
from typing import List
from transformers import GPT2LMHeadModel, GPT2Tokenizer
import torch

app = FastAPI()

class Query(BaseModel):
    question: str

class Response(BaseModel):
    answer: str

# Define the tools
class CalculatorTool(Tool):
    def run(self, params: dict) -> str:
        try:
            expression = params.get('expression', '')
            return str(eval(expression))
        except Exception as e:
            return f"Error: {str(e)}"

class TranslatorTool(Tool):
    def run(self, params: dict) -> str:
        text = params.get('text', '')
        lang = params.get('language', 'es')
        return f"Translated '{text}' to {lang} (mock result)"

# Initialize the GPT-2 model
model_name = "gpt2"
tokenizer = GPT2Tokenizer.from_pretrained(model_name)
model = GPT2LMHeadModel.from_pretrained(model_name)

# Define the bot
class BusinessAgent(LangChainAgent):
    def __init__(self, model, tokenizer, tools: List[Tool]):
        super().__init__(tools=tools)
        self.model = model
        self.tokenizer = tokenizer

    def generate_answer(self, question: str) -> str:
        inputs = self.tokenizer.encode(question, return_tensors='pt')
        outputs = self.model.generate(inputs, max_length=50)
        return self.tokenizer.decode(outputs[0], skip_special_tokens=True)

# Instantiate the bot with tools
bot = BusinessAgent(
    model=model,
    tokenizer=tokenizer,
    tools=[
        CalculatorTool(name='calculator'),
        TranslatorTool(name='translator')
    ]
)

@app.post("/query", response_model=Response)
async def handle_query(query: Query):
    try:
        answer = bot.generate_answer(query.question)
        return Response(answer=answer)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

