from abc import ABC, abstractmethod
import random

class Agent(ABC):
    @abstractmethod
    def perform_task(self, task):
        pass

class ResearchAgent(Agent):
    def __init__(self):
        self.name = "ResearcherAI"

    def perform_task(self, task):
        logger.info(f"{self.name} is gathering data on task: {task}")
        data = f"Comprehensive data for {task}"
        logger.info(f"{self.name} has completed data collection.")
        return data

class WritingAgent(Agent):
    def __init__(self):
        self.name = "WriterBot"

    def perform_task(self, data):
        logger.info(f"{self.name} is generating content based on the data.")
        content = f"Article based on: {data}"
        logger.info(f"{self.name} has completed article generation.")
        return content

class ReviewAgent(Agent):
    def __init__(self):
        self.name = "Reviewer3000"

    def perform_task(self, content):
        logger.info(f"{self.name} is reviewing the content.")
        feedback = "Approved" if random.choice([True, False]) else "Needs Revision"
        logger.info(f"{self.name} review result: {feedback}")
        return feedback

class CollaborativeSystem:
    def __init__(self):
        self.research_agent = ResearchAgent()
        self.writing_agent = WritingAgent()
        self.review_agent = ReviewAgent()

    def execute_task(self, task):
        data = self.research_agent.perform_task(task)
        content = self.writing_agent.perform_task(data)
        review_feedback = self.review_agent.perform_task(content)
        return review_feedback

def main():
    crew_system = CollaborativeSystem()
    task_description = "Developing a new marketing strategy"
    review_result = crew_system.execute_task(task_description)
    logger.info(f"Final Review Result: {review_result}")

if __name__ == "__main__":
    main()

