# Define the tools
class MathTool(Tool):
    def invoke(self, input: str) -> str:
        # Implement a simple math action
        return f"Math action processing: {input}"

class ScienceTool(Tool):
    def invoke(self, input: str) -> str:
        # Implement a simple science action
        return f"Science action processing: {input}"

# Create the agent
class AdaptiveTutorAgent(Agent):
    def __init__(self):
        self.tools = {
            "math": MathTool(),
            "science": ScienceTool()
        }

    def select_tool(self, context: dict) -> Tool:
        # Select action based on domain of question
        domain = context.get('domain', '').lower()
        return self.tools.get(domain, None)

