from langchain.tools import BaseTool, Tool

class MathQuizTool(BaseTool):
    def execute(self, student_input):
        # Provide a math problem based on student's current level
        return "Solve: 12 + 8"

class FeedbackTool(BaseTool):
    def execute(self, student_input):
        # Provide feedback based on student's answer
        if student_input.strip() == "20":
            return "Great job! That's correct."
        else:

            return "That's not quite right. Try again."


class AdaptiveTutoringAgent:
    def __init__(self):
        self.agent = Agent(
            model=ChatOpenAI(model_name="gpt-4.5-turbo"),
            tools=[
                Tool(name="MathQuiz", action=MethodInvoker(MathQuizTool()), description="Provide math problems."),
                Tool(name="Feedback", action=MethodInvoker(FeedbackTool()), description="Provide feedback on answers.")
            ],
            prompt=PromptTemplate.from_input("You are a math tutor who adapts to the student's level. Engage the student with questions and feedback.")
        )

        self.student_performance = {"correct": 0, "attempts": 0}

    def engage_student(self, student_input):
        if self.student_performance["attempts"] == 0:
            return self.agent.run("MathQuiz")
        else:
            feedback_response = self.agent.run("Feedback", student_input=student_input)
            if "correct" in feedback_response.lower():
                self.student_performance["correct"] += 1
            self.student_performance["attempts"] += 1
            return feedback_response

