from openai import OpenAI, ChatCompletion


class OrderSystem:
    def __init__(self):
        self.orders = {"12345": "Shipped", "67890": "Processing"}

    def get_order_status(self, order_id):
        return self.orders.get(order_id, "Order ID not found")

    def process_refund(self, order_id):
        if order_id in self.orders:
            return f"Refund initiated for order {order_id}"
        return "Invalid order ID"

    def update_customer_record(self, order_id, status):
        if order_id in self.orders:
            self.orders[order_id] = status
            return f"Order {order_id} status updated to {status}"
        return "Order ID not found"

class SupportAgent:
    def __init__(self, api_key, order_system):
        self.api_key = api_key
        self.order_system = order_system
        self.client = OpenAI(api_key=self.api_key)


    def handle_request(self, customer_query):
        response = self.client.ChatCompletion.create(
            model="gpt-4.1",
            messages=[{"role": "user", "content": customer_query}]
        )

        action = self.analyze_response(response.choices[0].message["content"])

        result = self.execute_action(action)

        return result

    def analyze_response(self, response_text):
        if "check status" in response_text:
            return "check_status"
        elif "refund" in response_text:
            return "initiate_refund"
        elif "update record" in response_text:
            return "update_record"
        else:
            return "unknown"


    def execute_action(self, action):
        if action == "check_status":
            return self.order_system.get_order_status("12345")
        elif action == "initiate_refund":
            return self.order_system.process_refund("12345")
        elif action == "update_record":
            return self.order_system.update_customer_record("12345", "Cancelled")
        else:
            return "Action not recognized"

