from typing import List, Dict, Any

class AdaptiveTutorAgent(Agent):
    def __init__(self, api_key: str, initial_difficulty: float = 0.5):
        super().__init__()
        self.llm = OpenAI(api_key=api_key)
        self.difficulty = initial_difficulty

    def adjust_difficulty(self, student_performance: float):
        if student_performance > 0.8:
            self.difficulty = min(self.difficulty + 0.1, 1.0)
        elif student_performance < 0.5:
            self.difficulty = max(self.difficulty - 0.1, 0.0)

