from crewai import MultiAgentSystem, Agent, Task

# Define Agent roles
class Researcher(Agent):
    def __init__(self):
        super().__init__(name="Researcher")

    def execute(self, task_data):
        # Simulate research process
        research_result = f"Findings on {task_data['topic']}: Comprehensive data collected."
        return {"research_result": research_result}

class Writer(Agent):
    def __init__(self):
        super().__init__(name="Writer")

    def execute(self, task_data):
        # Craft article based on research
        article = f"Article based on {task_data['research_result']}: Well-written draft created."
        return {"article": article}

class Reviewer(Agent):
    def __init__(self):
        super().__init__(name="Reviewer")

    def execute(self, task_data):
        # Review and provide feedback
        feedback = f"Review of {task_data['article']}: Excellent structure and clarity."
        return {"feedback": feedback}

# Define the task workflow
class ArticleCreationTask(Task):
    def __init__(self, topic):
        self.topic = topic
        super().__init__(steps=[
            {"agent": Researcher(), "input": {"topic": self.topic}},
            {"agent": Writer(), "input": {"research_result": "research_result"}},
            {"agent": Reviewer(), "input": {"article": "article"}}
        ])

# Initialize the MultiAgentSystem
class EditorialSystem(MultiAgentSystem):
    def __init__(self):
        super().__init__(name="EditorialSystem", agents=[Researcher(), Writer(), Reviewer()])

    def create_article(self, topic):
        task = ArticleCreationTask(topic)
        return self.execute_task(task)

# Example usage
if __name__ == "__main__":
    editorial_system = EditorialSystem()
    result = editorial_system.create_article("The Impact of AI in Healthcare")
