    def __init__(self):
        self.name = "DataFetcher"

    def fetch(self, source):
        # Simulating data fetching
        return [{"id": i, "value": i * 10} for i in range(1, 101)]

# Register tools
tool_registry = ToolRegistry()
analyzer_tool = DataAnalyzerTool()
fetcher_tool = DataFetcherTool()

tool_registry.register_tool(analyzer_tool.name, analyzer_tool)
tool_registry.register_tool(fetcher_tool.name, fetcher_tool)

# Define agents
class AssistantAgent(Agent):

    def __init__(self, model):
        super().__init__(model, tool_registry)

    def perform_analysis(self, resource):
        data = self.tools["DataFetcher"].fetch(resource)
        result = self.tools["DataAnalyzer"].analyze(data)
        return result

class UserProxyAgent(Agent):
    def __init__(self, model):
        super().__init__(model, tool_registry)

    def request_analysis(self, resource):
        return self.model.perform_analysis(resource)

