import anthropic

class AutonomousAgent:
    def __init__(self):
        self.ai = anthropic.AI()

    def execute_task(self, task_data):
        task_result = self.ai.perform_task(task_data)
        if task_result.success:
            self.finalize_task(task_result)
        else:
            self.log_issue(task_result)

    def finalize_task(self, result):
        print('Task successfully completed:', result)

    def log_issue(self, result):
        print('Task failed:', result)

