from langchain.embeddings import OpenAIEmbedding


class ProductDescriptionEmbedding:

    def __init__(self, api_key: str):
        self.embedding_service = OpenAIEmbedding(api_key=api_key, model='text-embedding-ada-002')

    def generate_embeddings(self, descriptions: list) -> list:

        return [self.embedding_service.get_embedding(description) for description in descriptions]

def check_compliance(embeddings: list) -> bool:
    threshold = 0.7
    for emb in embeddings:
        if max(emb) > threshold:

            return False
    return True


def main():

    api_key = "your_api_key_here"

    product_descriptions = [

        "High-quality leather wallet with RFID protection.",
        "Eco-friendly bamboo toothbrush with soft bristles.",
        "Stainless steel water bottle with vacuum insulation."
    ]

    embedder = ProductDescriptionEmbedding(api_key)
    embeddings = embedder.generate_embeddings(product_descriptions)

    if check_compliance(embeddings):
        print("All descriptions are compliant.")
    else:
        print("Some descriptions are not compliant.")

if __name__ == "__main__":
    main()

