from crewai import Crew, Agent, Task


class Researcher(Agent):
    def __init__(self):
        super().__init__(role_name="Researcher")

    def handle_task(self, task: Task):
        topic = task.data.get("topic")
        research_data = f"Collected data and insights about {topic} for analysis."
        self.send_to_next({"research_data": research_data})



class Writer(Agent):
    def __init__(self):

        super().__init__(role_name="Writer")

    def handle_task(self, task: Task):
        research_content = task.data.get("research_data")
        draft_text = f"Drafted article based on research: {research_content}"
        self.send_to_next({"draft_text": draft_text})


class Reviewer(Agent):
    def __init__(self):
        super().__init__(role_name="Reviewer")

    def handle_task(self, task: Task):
        draft_content = task.data.get("draft_text")

        feedback = f"Review Feedback: Refine sections for clarity. Original draft: {draft_content}"
        self.complete_task({"feedback": feedback})

class CollaborativeWritingTask(Task):
    def __init__(self, topic):
        super().__init__(work_process=[
            Researcher(),
            Writer(),
            Reviewer()
        ])

        self.data = {"topic": topic}

crew = Crew("ArticleCreationTeam", task_class=CollaborativeWritingTask)

