from crewai.agents import Agent
from crewai.environment import CollaborationEnvironment
from crewai.tools import DataParser, TextSynthesizer, ReviewChecker
from crewai.models import KnowledgeModelV2, WritingModelV3, ReviewModelV1

class ResearcherAgent(Agent):
    def __init__(self):
        super().__init__()
        self.parser = DataParser(model=KnowledgeModelV2())

    def perform_task(self, task_description):
        data = self.parser.extract_data(task_description.subject, task_description.scope)
        return {"research_data": data}


class WriterAgent(Agent):

    def __init__(self):
        super().__init__()
        self.synthesizer = TextSynthesizer(model=WritingModelV3())

    def perform_task(self, task_inputs):
        content = self.synthesizer.generate_content(task_inputs["research_data"])
        return {"draft": content}

class ReviewerAgent(Agent):
    def __init__(self):
        super().__init__()
        self.checker = ReviewChecker(model=ReviewModelV1())

    def perform_task(self, task_inputs):
        feedback = self.checker.perform_review(task_inputs["draft"])
        return feedback

class CollaborationTask:
    def __init__(self, subject, scope):
        self.subject = subject
        self.scope = scope

def main():
    env = CollaborationEnvironment()

    researcher = ResearcherAgent()
    writer = WriterAgent()
    reviewer = ReviewerAgent()

    task_description = CollaborationTask(subject="AI Ethics", scope="Current Trends and Challenges")

    research_result = researcher.perform_task(task_description)
    writing_result = writer.perform_task(research_result)
    review_feedback = reviewer.perform_task(writing_result)


    print("Final Review Feedback:", review_feedback)

if __name__ == "__main__":
    main()

