        self.complete_task(task, document)

class ReviewerAgent(Agent):
    def setup(self):

        self.name = 'Reviewer'
        self.role = 'Reviews and edits the document for accuracy and coherence.'

    def perform_task(self, task: Task):

        # Review and edit document
        edited_document = f"Edited document: {task.input_data}"
        self.complete_task(task, edited_document)

