from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

from typing import List, Dict, Any
from langchain import Agent, Tool, LLMMultiTool
from langchain.models import OpenAI

app = FastAPI()


class QueryRequest(BaseModel):
    input_text: str
    tools: List[str]

class QueryResponse(BaseModel):
    response: str

class ToolInfo(BaseModel):
    name: str
    description: str


tools_catalog: Dict[str, Tool] = {
    "weather_reporter": Tool(
        name="weather_reporter",
        description="Provides weather information for a given location",
        func=lambda location: f"Current weather at {location} is sunny with 24?C."
    ),
    "stock_analyzer": Tool(
        name="stock_analyzer",
        description="Analyzes stock trends based on historical data",
        func=lambda symbol: f"The stock {symbol} is on an upward trend."
    ),
}

llm_agent = Agent(
    llm=OpenAI(model="gpt-4.5"),
    tools=[tool for tool in tools_catalog.values()],
)

@app.post("/query", response_model=QueryResponse)
async def query_agent(request: QueryRequest):
    try:
        selected_tools = [tools_catalog[name] for name in request.tools if name in tools_catalog]
        if not selected_tools:
            raise ValueError("No valid tools provided.")

        llm_agent.tools = selected_tools
        result = llm_agent.run(input_text=request.input_text)
        return QueryResponse(response=result)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))

@app.get("/tools", response_model=List[ToolInfo])
async def get_tools():
    return [ToolInfo(name=tool.name, description=tool.description) for tool in tools_catalog.values()]

import asyncio
import logging
import json
import os
from datetime import datetime
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,
    PermissionResultAllow, PermissionResultDeny,
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
os.makedirs("./audit", exist_ok=True)

DANGEROUS_COMMANDS = ["rm -rf", "sudo", "chmod 777", "mkfs"]

async def block_dangerous_bash(input_data, tool_use_id, context):
    """Block dangerous bash commands."""
    if input_data.get("tool_name") == "Bash":
        cmd = input_data.get("tool_input", {{}}).get("command", "")
        for pattern in DANGEROUS_COMMANDS:
            if pattern in cmd:
                logger.warning(f"Blocked dangerous command: {{cmd}}")
                return {{
                    "hookSpecificOutput": {{
                        "hookEventName": "PreToolUse",
                        "permissionDecision": "deny",
                        "permissionDecisionReason": f"Dangerous: {{pattern}}",
                    }}
                }}
    return {{}}

async def audit_log(input_data, tool_use_id, context):
    """Log every action result to audit directory."""
    record = {{
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "action": input_data.get("tool_name"),
        "tool_use_id": tool_use_id,
    }}
    fname = f"./audit/{{tool_use_id or 'unknown'}}.json"
    with open(fname, "w") as f:
        json.dump(record, f)
    return {{}}

async def permission_handler(tool_name, input_data, context):
    """Risk-based permission handler."""
    if tool_name == "Bash":
        cmd = input_data.get("command", "")
        if any(p in cmd for p in DANGEROUS_COMMANDS):
            return PermissionResultDeny(message="Blocked by policy")
    return PermissionResultAllow(updated_input=input_data)

async def main():
    options = ClaudeAgentOptions(
        allowed_tools=["Read", "Write", "Bash"],
        can_use_tool=permission_handler,
        max_turns=10,
        hooks={{
            "PreToolUse": [
                HookMatcher(matcher="Bash", hooks=[block_dangerous_bash]),
            ],
            "PostToolUse": [HookMatcher(hooks=[audit_log])],
        }},
    )
    async with ClaudeSDKClient(options=options) as client:
        await client.query("Generate a marketing plan for Q2")
        async for message in client.receive_response():
            print(message)

asyncio.run(main())

