from typing import Dict, Any

# Define the LLM prompt for claims evaluation
def claims_evaluation_prompt(document_text: str) -> str:
    return f"""
    You are an assistant designed to evaluate insurance claims. Review the following document and provide a payout recommendation:

    Document:
    {document_text}

    Recommendation:
    """

# Define the LLM tool for processing insurance documents
class InsuranceReviewTool(Tool):
    def __init__(self, model_name: str = "openai-gpt-4.5"):
        super().__init__(name="InsuranceReviewTool")
        self.llm = OpenAI(model_name=model_name)

    def run(self, document: Dict[str, Any]) -> str:
        prompt = claims_evaluation_prompt(document["text"])
        return self.llm(prompt=prompt)

# Define the agent that will process the claims
class ClaimsProcessorAgent:
    def __init__(self, toolset: ToolSet):
        self.executor = AgentExecutor(toolset=toolset)

    def process_claim(self, claim_document: Dict[str, Any]) -> str:
        return self.executor.run_tool("InsuranceReviewTool", claim_document)

# Create the toolset for the agent
insurance_tools = ToolSet(tools=[InsuranceReviewTool()])

# Instantiate the claims processing agent
claims_processor = ClaimsProcessorAgent(toolset=insurance_tools)

