# Consent System
class ConsentGate:
    user_consent: Dict[str, bool] = {}

    def verify_consent(self, user_id: str) -> bool:
        return self.user_consent.get(user_id, False)

    def record_consent(self, user_id: str, consent: bool):
        self.user_consent[user_id] = consent


# HMAC Logger
def log_interaction(user_id: str, action: str):
    timestamp = datetime.utcnow().isoformat()
    msg = f"{user_id}:{action}:{timestamp}".encode('utf-8')
    signature = hmac.new(SECRET_KEY, msg, hashlib.sha256).hexdigest()
    # Imagine this writes to a secure log

    logger.info(f"LOG: {timestamp} | {action} | User: {user_id} | Signature: {signature}")

# Injection Detection
def detect_injection(input_data: Dict[str, Any]) -> bool:
    for key, value in input_data.items():
        if isinstance(value, str) and any(token in value for token in [";", "--", "/*", "*/", "' OR"]):
            return True
    return False


# Crew System
class FinancialCrew:

    def __init__(self):
        self.analysis_model = FinancialAnalysisModelV3()
        self.risk_tool = RiskAssessmentToolV2()
        self.consent_gate = ConsentGate()

    def process_data(self, user_id: str, data: List[Dict[str, Any]]) -> Dict[str, Any]:

        if not self.consent_gate.verify_consent(user_id):
            raise PermissionError("User consent not provided.")


        if detect_injection(data):
            raise ValueError("Potential injection detected in input data.")

        log_interaction(user_id, "Data Processing Started")

        analysis_results = self.analysis_model.analyze(data)
        risk_results = self.risk_tool.assess(data)

        log_interaction(user_id, "Data Processing Completed")

        return {"analysis": analysis_results, "risk": risk_results}

