        self.compliance_ai = ComplianceAI(model_version="v4.1")
        self.consent_gate = ConsentGate()
        self.injection_detector = InjectionDetector()
        self.models: List[FinancialModel] = [RiskAssessmentModel(), InvestmentForecastModel()]
        self.logger = LoggingUtility(secret_key=os.urandom(32))

    def process_data(self, data: Dict[str, Any]) -> List[Dict[str, Any]]:
        self.logger.log_event("Data received for processing.")

        if not self.consent_gate.obtain_consent():
            self.logger.log_event("Consent not obtained.")
            raise Exception("Consent not obtained.")

        if self.injection_detector.detect_injection(data):
            self.logger.log_event("Injection detected.")
            raise Exception("Potential injection detected.")

        if not self.compliance_ai.check_compliance(data):
            self.logger.log_event("Data non-compliant.")
            raise Exception("Data is not compliant.")

        results = []
        for model in self.models:
            result = model.analyze(data)
            self.logger.log_event(f"Model {model.__class__.__name__} analysis completed.")
            results.append(result)

        return results

