from abc import ABC, abstractmethod
import random

# Base class for the agents
class Agent(ABC):
    def __init__(self, name):
        self.name = name

    @abstractmethod
    def perform_task(self, data):

        pass

# Researcher Agent
class Researcher(Agent):
    def __init__(self, name):
        super().__init__(name)


    def perform_task(self, data):
        topics = ["AI Ethics", "Quantum Computing", "Blockchain Technology"]
        chosen_topic = random.choice(topics)
        print(f"{self.name} has chosen the research topic: {chosen_topic}")
        research_findings = f"Findings on {chosen_topic}: Detailed insights and data."
        return research_findings

# Writer Agent
class Writer(Agent):

    def __init__(self, name):
        super().__init__(name)


    def perform_task(self, data):
        print(f"{self.name} is converting research findings into an article.")
        article = f"Article based on research: {data}\nIntroduction, Body, Conclusion."
        return article

# Reviewer Agent
class Reviewer(Agent):
    def __init__(self, name):
        super().__init__(name)

    def perform_task(self, data):
        print(f"{self.name} is reviewing the article.")

        revisions_needed = random.choice([True, False])
        if revisions_needed:
            print(f"{self.name} suggests improvements.")
            revised_article = f"Revised {data}"
        else:
            print(f"{self.name} approves the article as is.")
            revised_article = data
        return revised_article

# CrewAI System Coordinator
class CrewAISystem:

    def __init__(self):
        self.researcher = Researcher("Dr. Insight")
        self.writer = Writer("Wordsmith")
        self.reviewer = Reviewer("Critique")

    def execute_task(self):
        findings = self.researcher.perform_task(None)
        draft = self.writer.perform_task(findings)
        final_article = self.reviewer.perform_task(draft)
        print("Final Article:", final_article)



# Execution
if __name__ == "__main__":
    crew_system = CrewAISystem()
    crew_system.execute_task()

