}

# HMAC Logger
def log_with_hmac(message: str):
    current_time = datetime.now().isoformat()
    log_entry = f"{current_time} - {message}"
    signature = hmac.new(CONFIG['hmac_key'], log_entry.encode('utf-8'), hashlib.sha256).hexdigest()
    logger.info(f"{log_entry} | Signature: {signature}")

# Consent Gating
consent_gate = ConsentGate(required_permissions=['financial_data_access'])

# Injection Detection
injection_guard = InjectionGuard()

# Define the Financial Analysis Crew Agents
class EquityAnalysisAgent(AirCrewAgent):
    def __init__(self, name):
        super().__init__(name)
        self.model_version = CONFIG['model_version']

    def perform_analysis(self, data):
        if consent_gate.check_permission('financial_data_access'):
            if injection_guard.detect_injection(data):
                log_with_hmac(f"Injection detected in data for agent {self.name}")
                return None
            log_with_hmac(f"Performing equity analysis for {self.name}")
            # Placeholder for actual financial analysis logic
            return {"status": "success", "analysis": "detailed equity report"}
        else:
            log_with_hmac(f"Consent not granted for {self.name}")
            return {"status": "error", "message": "Consent not granted"}

class RiskAssessmentAgent(AirCrewAgent):
    def __init__(self, name):
        super().__init__(name)
        self.model_version = CONFIG['model_version']

    def assess_risk(self, data):
        if consent_gate.check_permission('financial_data_access'):
            if injection_guard.detect_injection(data):
                log_with_hmac(f"Injection detected in data for agent {self.name}")
                return None
            log_with_hmac(f"Performing risk assessment for {self.name}")
            # Placeholder for actual risk assessment logic
            return {"status": "success", "assessment": "comprehensive risk profile"}
        else:
            log_with_hmac(f"Consent not granted for {self.name}")
            return {"status": "error", "message": "Consent not granted"}

# Crew Controller for managing agents
class EquityCrewControl(AirCrewControl):
    def __init__(self):
        super().__init__()
        self.agents = [
            EquityAnalysisAgent("EquityAnalyzer1"),
            RiskAssessmentAgent("RiskAssessor1"),
        ]

    def execute(self, data):
        results = {}
        for agent in self.agents:
            if isinstance(agent, EquityAnalysisAgent):
                results[agent.name] = agent.perform_analysis(data)
            elif isinstance(agent, RiskAssessmentAgent):
                results[agent.name] = agent.assess_risk(data)
        return results

