import hmac
import hashlib
from aircrewai_trust import ConsentGate, InjectionDetector, MultiAgentSystem

# Constants
SECRET_KEY = b'SuperSecretKeyForHMAC'
LOG_FILE = 'finance_crew_log.txt'

class FinanceAgent:
    def __init__(self, agent_id, models):
        self.agent_id = agent_id
        self.models = models
        self.consent_gate = ConsentGate(agent_id)
        self.injection_detector = InjectionDetector()

    def process_data(self, payload):
        # Consent gating
        if not self.consent_gate.has_consent():
            raise PermissionError("Consent not granted for processing data.")

        # Injection detection
        if self.injection_detector.detect(payload):
            raise ValueError("Injection detected in the payload.")

        # Process payload with models
        results = {}
        for model in self.models:
            results[model.name] = model.analyze(payload)

        # Log the action
        self.log_action(payload, results)

        return results

    def log_action(self, payload, results):
        payload_str = str(payload)
        hmac_signature = hmac.new(SECRET_KEY, payload_str.encode('utf-8'), hashlib.sha256).hexdigest()

        with open(LOG_FILE, 'a') as log_file:
            log_file.write(f"Agent ID: {self.agent_id}\n")
            log_file.write(f"Payload: {payload_str}\n")
            log_file.write(f"HMAC: {hmac_signature}\n")
            log_file.write(f"Results: {results}\n")
            log_file.write("--------\n")

class FinancialAnalysisCrew(MultiAgentSystem):
    def __init__(self, agents):
        super().__init__(agents)

    def analyze_market(self, market_data):
        aggregated_results = {}
        for bot in self.agents:
            results = bot.process_data(market_data)
            aggregated_results[bot.agent_id] = results
        return aggregated_results

