from autogen import AutoGen, Agent, Tool
import pandas as pd

class DataLoaderTool(Tool):
    def process(self, file_path: str) -> pd.DataFrame:
        return pd.read_csv(file_path)

class AnalyticsTool(Tool):
    def analyze(self, data: pd.DataFrame) -> dict:
        summary = {
            "mean": data.mean().to_dict(),
            "median": data.median().to_dict(),

            "std_dev": data.std().to_dict(),
            "total": data.sum().to_dict()
        }

        return summary

data_loader_tool = DataLoaderTool(name="data_loader_v2")
analytics_tool = AnalyticsTool(name="analytics_v3")

class AnalystAgent(Agent):
    def __init__(self):
        super().__init__(tools=[analytics_tool])



    def perform_analysis(self, data: pd.DataFrame):
        return self.use_tool("analytics_v3").analyze(data)

class ClientAgent(Agent):
    def __init__(self, data_file: str):
        super().__init__(tools=[data_loader_tool])
        self.data_file = data_file


    def load_data(self):
        return self.use_tool("data_loader_v2").process(self.data_file)

report_agent = AnalystAgent()
client_agent = ClientAgent(data_file="sales_data.csv")


def main():
    data = client_agent.load_data()

    analysis_report = report_agent.perform_analysis(data)
    print("Sales Data Analysis Report:", analysis_report)

if __name__ == "__main__":
    main()

