# Create ChatBot agent
class HealthcareChatBot(ChatBotAgent):
    def __init__(self, language_model, tools):
        super().__init__(language_model, tools)

    def handle_message(self, message, context):
        if 'patient_id' in message:
            patient_data = self.tools['PatientRecordTool'].execute(message['patient_id'])
            return f"Patient Data: {patient_data}"
        elif 'medical_query' in message:
            medical_info = self.tools['MedicalInfoTool'].execute(message['medical_query'])
            return f"Medical Info: {medical_info}"
        else:
            return "Please provide a valid input."

