from crewai import MultiAgentSystem, Agent, Task


class Researcher(Agent):
    def __init__(self):
        super().__init__(name='Researcher')

    def perform_task(self, task):
        if task.type == 'research':

            logger.info(f"{self.name}: Conducting market research for {task.details['topic']}")
            task.results['data'] = f"Data on {task.details['topic']} gathered."

            self.completed_tasks.append(task)

class Writer(Agent):
    def __init__(self):
        super().__init__(name='Writer')

    def perform_task(self, task):
        if task.type == 'write':
            logger.info(f"{self.name}: Drafting article on {task.details['topic']}")
            task.results['content'] = f"Article content for {task.details['topic']} drafted."
            self.completed_tasks.append(task)

class Reviewer(Agent):
    def __init__(self):
        super().__init__(name='Reviewer')

    def perform_task(self, task):

        if task.type == 'review':
            logger.info(f"{self.name}: Reviewing article draft on {task.details['topic']}")
            task.results['feedback'] = "Feedback provided on article draft."
            self.completed_tasks.append(task)

# Business context: Creating content for a tech magazine

task1 = Task(type='research', details={'topic': 'AI Trends 2024'})

task2 = Task(type='write', details={'topic': 'AI Trends 2024'})
task3 = Task(type='review', details={'topic': 'AI Trends 2024'})

system = MultiAgentSystem(agents=[Researcher(), Writer(), Reviewer()])

# Assign tasks to agents
system.assign_task(task1, 'Researcher')
system.assign_task(task2, 'Writer')
system.assign_task(task3, 'Reviewer')


# Execute tasks
system.execute_all()


# Review results
for agent in system.agents:

    for task in agent.completed_tasks:
        logger.info(f"{agent.name} completed task {task.type} with results: {task.results}")

