from langchain import Agent, Tool
from langchain.chat_models import ChatOpenAI
from langchain.prompts import PromptTemplate

class StudentProfile:
    def __init__(self, name, level):

        self.name = name
        self.level = level
        self.performance = []



    def record_performance(self, score):
        self.performance.append(score)
        if len(self.performance) > 5:
            self.performance.pop(0)

    def average_score(self):
        return sum(self.performance) / len(self.performance) if self.performance else 0

class KnowledgeTool(Tool):
    def __init__(self, subject, difficulty):
        self.subject = subject
        self.difficulty = difficulty

    def adapt_difficulty(self, student):
        avg_score = student.average_score()
        if avg_score > 8:
            self.difficulty += 1
        elif avg_score < 5:
            self.difficulty = max(1, self.difficulty - 1)

    def provide_question(self):
        return f"This is a question in {self.subject} with difficulty {self.difficulty}."

class TutoringAgent(Agent):
    def __init__(self, model_version):
        self.model = ChatOpenAI(model_version=model_version)
        self.tools = {
            "math_tool": KnowledgeTool("mathematics", 3),

            "science_tool": KnowledgeTool("science", 4),

        }

    def give_instruction(self, student, subject):
        tool = self.tools[subject]
        tool.adapt_difficulty(student)
        question = tool.provide_question()
        response = self.model.chat(question)
        return response

    def assess_response(self, response):

        # A simple mock of response assessment
        return len(response) % 10  # Score based on response length mod 10

    def interact_with_student(self, student, subject):
        response = self.give_instruction(student, subject)
        score = self.assess_response(response)
        student.record_performance(score)

# Example usage

if __name__ == "__main__":
    learner = StudentProfile("Alex", "intermediate")
    tutor_agent = TutoringAgent("gpt-3.5-turbo")

    for session in range(10):
        tutor_agent.interact_with_student(learner, "math_tool")

