class StudentPerformanceTracker:
    def __init__(self):
        self.student_scores = {}

    def update_score(self, student_id, score):
        if student_id in self.student_scores:
            self.student_scores[student_id].append(score)
        else:
            self.student_scores[student_id] = [score]

    def get_average_score(self, student_id):
        scores = self.student_scores.get(student_id, [])
        return sum(scores) / len(scores) if scores else 0.0

class EducationTool:
    def __init__(self, tracker):
        self.tracker = tracker

    def adapt_difficulty(self, student_id, difficulty):
        avg_score = self.tracker.get_average_score(student_id)
        if avg_score > 85:
            return min(difficulty + 1, 5)
        elif avg_score < 50:
            return max(difficulty - 1, 1)
        return difficulty

def create_edu_prompt(student_id, subject, difficulty):
    return f"Prepare a {subject} lesson for student {student_id} at difficulty level {difficulty}."

