    def __init__(self, tracker):
        self.tracker = tracker
        self.tool = EducationTool(tracker)
        self.ai_model = ChatOpenAI(model_name="gpt-4.1")

    def generate_lesson(self, student_id, subject, initial_difficulty):
        adapted_difficulty = self.tool.adapt_difficulty(student_id, initial_difficulty)
        instruction = create_edu_prompt(student_id, subject, adapted_difficulty)
        response = self.ai_model.generate_response(instruction=instruction)
        return response

