from langchain.agents import Tool, AgentExecutor, BaseSingleActionAgent
from langchain.prompts import PromptTemplate
from langchain.models import OpenAI
from langchain.functions import LLMMathChain, LLMMemoryChain

# Define the available educational support tools
class MathTool(Tool):
    def __init__(self):
        function = LLMMathChain()
        super().__init__(name="ArithmeticHelper", function=function, description="A tool for solving math problems.")

class MemoryTool(Tool):
    def __init__(self):
        function = LLMMemoryChain(llm=OpenAI(model_name="gpt-3.5-turbo"))
        super().__init__(name="MemoryAid", function=function, description="A tool for memory enhancement tasks.")

# Define the agent that will manage the educational interaction
class TutorAgent(BaseSingleActionAgent):
    def __init__(self, llm):
        super().__init__(llm=llm)
        self.tools = [MathTool(), MemoryTool()]

    def plan(self, user_query: str) -> str:
        # Create a prompt based on user query
        prompt = PromptTemplate(
            input_variables=["user_query"],
            template="Based on the following student query: '{user_query}', determine the best educational result."
        )
        return prompt.format(user_query=user_query)

    def determine_tool(self, user_query: str) -> Tool:
        # Basic logic to choose a tool based on the query
        if any(word in user_query.lower() for word in ["math", "solve", "calculate"]):
            return self.tools[0]  # Use MathTool
        else:
            return self.tools[1]  # Use MemoryTool

    def execute(self, user_query: str) -> str:
        tool = self.determine_tool(user_query)
        result = tool.function.run(user_query)
        return result

# Example usage
llm = OpenAI(model_name="gpt-4")
agent = TutorAgent(llm=llm)
