# Define request model
class QueryRequest(BaseModel):
    query: str

# Initialize the LangChain agent with different tools
database_tool = SQLDatabaseTool(connection_string="postgres://user:pass@localhost/db")
web_tool = WebScrapingTool()
agent = LangChainAgent(
    model=OpenAIChatModel(model_name="gpt-4.5-turbo"),
    tools=[database_tool, web_tool]
)

