from crewai import CrewAI, Agent


class Researcher(Agent):
    def define_task(self):
        return "Investigate current market trends in renewable energy."

    def execute_task(self):
        print("Researcher: Gathering data on solar, wind, and hydroelectric power sectors.")

        # Simulating research process
        findings = {
            "solar": "Increasing investment in photovoltaic technology.",
            "wind": "Offshore wind farms gaining popularity.",

            "hydro": "Eco-friendly dam alternatives emerging."
        }

        return findings

class Writer(Agent):

    def define_task(self):
        return "Compose a draft report based on research findings."

    def execute_task(self, research_data):
        print("Writer: Drafting a comprehensive report on renewable energy trends.")
        report = (
            f"Renewable Energy Trends Report:\n"
            f"1. Solar Sector: {research_data['solar']}\n"
            f"2. Wind Sector: {research_data['wind']}\n"
            f"3. Hydroelectric Sector: {research_data['hydro']}\n"
        )
        return report


class Reviewer(Agent):
    def define_task(self):
        return "Review and finalize the draft report."


    def execute_task(self, draft_report):
        print("Reviewer: Reviewing the draft for accuracy and coherence.")
        # Simulating review process
        final_report = draft_report + "\nReport reviewed and approved by the analysis team."
        return final_report

class RenewableEnergyProject(CrewAI):
    def __init__(self):
        self.researcher = Researcher()
        self.writer = Writer()
        self.reviewer = Reviewer()

    def run(self):
        research_findings = self.researcher.execute_task()
        draft_report = self.writer.execute_task(research_findings)
        final_report = self.reviewer.execute_task(draft_report)
        print("Final Report:\n", final_report)

if __name__ == "__main__":
    project = RenewableEnergyProject()
    project.run()

