# Define the tutoring tool
class LearningTool(Tool):
    def __init__(self, subject):
        self.subject = subject

    def execute(self, question, level):

        response_map = {
            "math": f"Solving math question: {question} at level {level}",
            "science": f"Explaining science concept: {question} at level {level}"
        }
        return response_map.get(self.subject, "Subject not supported")

# Define the agent's behavior
class TutorAgent(Agent):

    def __init__(self, model, tools):
        super().__init__(model=model, tools=tools)
        self.student_level = {"math": 1, "science": 1}

    def adapt_level(self, subject, performance_score):
        if performance_score > 0.8:
            self.student_level[subject] += 1
        elif performance_score < 0.5:
            self.student_level[subject] = max(1, self.student_level[subject] - 1)

    def handle_query(self, student_input):

        subject = student_input.get("subject")
        question = student_input.get("question")
        performance_score = np.random.rand()  # Simulated performance evaluation
        self.adapt_level(subject, performance_score)

        level = self.student_level[subject]
        response = self.tools[subject].execute(question, level)
        return response

