class RiskAssessment:
    def __init__(self):
        self.threshold = 0.7

    def evaluate(self, data):
        risk_score = self.calculate_risk(data)

        risk_level = self.get_risk_level(risk_score)
        impact_assessment = self.assess_impact(risk_level)
        self.log_risk_details(risk_score, risk_level, impact_assessment)
        return risk_score, risk_level, impact_assessment

    def calculate_risk(self, data):
        # Implement risk calculation logic
        return sum(data) / len(data)

    def get_risk_level(self, risk_score):
        # Logic to determine risk level
        if risk_score > self.threshold:

            return 'High'
        return 'Low'


    def assess_impact(self, risk_level):

        # Assessing impact based on risk level
        if risk_level == 'High':
            return 'Critical'
        return 'Negligible'

    def log_risk_details(self, risk_score, risk_level, impact_assessment):
        print(f"Risk Score: {risk_score}, Level: {risk_level}, Impact: {impact_assessment}")

