    def __init__(self, model, tools):
        self.model = model
        self.tools = tools
        self.memory = Memory()

    def chat(self, user_input):
        context = self.memory.get_context()
        tool_results = {name: tool(user_input, context) for name, tool in self.tools.items()}
        result = self.model.generate_response(user_input, tool_results)
        self.memory.update_context(result)
        return result

