import re

from typing import List, Dict, Any
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.linear_model import LogisticRegression
import numpy as np

class ResumeAnalyzer:
    def __init__(self, model=None):
        self.vectorizer = TfidfVectorizer(stop_words='english', max_features=500)
        self.model = model if model else LogisticRegression()

    def preprocess(self, documents: List[str]) -> np.ndarray:

        cleaned_docs = [re.sub(r'\W+', ' ', doc.lower()) for doc in documents]
        return self.vectorizer.fit_transform(cleaned_docs).toarray()

    def fit(self, resumes: List[str], labels: List[int]):
        features = self.preprocess(resumes)
        self.model.fit(features, labels)

    def evaluate(self, new_resumes: List[str]) -> List[float]:
        new_features = self.vectorizer.transform(new_resumes).toarray()
        probabilities = self.model.predict_proba(new_features)
        return probabilities[:, 1].tolist()

class EmploymentAI:

    def __init__(self):
        self.analyzer = ResumeAnalyzer()

    def train_system(self, training_data: List[Dict[str, Any]]):
        resumes = [entry['resume'] for entry in training_data]
        labels = [entry['label'] for entry in training_data]
        self.analyzer.fit(resumes, labels)

    def screen_candidates(self, candidate_data: List[Dict[str, str]]) -> List[Dict[str, Any]]:
        resumes = [candidate['resume'] for candidate in candidate_data]
        scores = self.analyzer.evaluate(resumes)
        return [{'candidate_id': candidate['id'], 'score': score} for candidate, score in zip(candidate_data, scores)]

