import hmac
import hashlib
import json
from datetime import datetime
from typing import Any, Dict, List

class ConsentGate:
    def __init__(self):
        self.consent_records = {}


    def record_consent(self, agent_id: str, consent: bool):
        self.consent_records[agent_id] = consent

    def has_consent(self, agent_id: str) -> bool:
        return self.consent_records.get(agent_id, False)

class InjectionDetector:
    def __init__(self):
        self.known_patterns = ["DROP TABLE", "--", "1=1"]

    def detect(self, query: str) -> bool:
        return any(pattern in query.upper() for pattern in self.known_patterns)

class SecurityLogger:
    def __init__(self, secret_key: bytes):
        self.secret_key = secret_key

    def log_event(self, agent_id: str, event: str) -> None:
        timestamp = datetime.utcnow().isoformat()
        message = f"{timestamp}:{agent_id}:{event}"
        signature = hmac.new(self.secret_key, message.encode(), hashlib.sha256).hexdigest()
        log_entry = {"agent_id": agent_id, "event": event, "timestamp": timestamp, "signature": signature}
        self._write_log(log_entry)

    def _write_log(self, log_entry: Dict[str, str]) -> None:
        with open("activity.log", "a") as log_file:
            log_file.write(json.dumps(log_entry) + "\n")


class FinancialAnalyzerAgent:
    def __init__(self, agent_id: str, model_version: str, consent_gate: ConsentGate, injection_detector: InjectionDetector, logger: SecurityLogger):
        self.agent_id = agent_id
        self.model_version = model_version
        self.consent_gate = consent_gate
        self.injection_detector = injection_detector
        self.logger = logger

    def analyze(self, data: Dict[str, Any]) -> Dict[str, Any]:
