import re
import json
from typing import List, Dict

from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.ensemble import RandomForestClassifier

class ResumeParser:
    def __init__(self):
        self.vectorizer = TfidfVectorizer(stop_words='english', max_features=500)

    def parse(self, resume_text: str) -> List[str]:

        # Simple regex-based extraction of words
        words = re.findall(r'\b\w+\b', resume_text.lower())
        return words

class EvaluationModel:
    def __init__(self):
        self.model = RandomForestClassifier(n_estimators=100, random_state=42)
        self.trained = False

    def train(self, X: List[List[str]], y: List[int]):
        X_vectorized = [" ".join(words) for words in X]
        X_tfidf = self.vectorizer.fit_transform(X_vectorized)
        self.model.fit(X_tfidf, y)
        self.trained = True

    def evaluate(self, resume_terms: List[str]) -> float:
        if not self.trained:
            raise Exception("Model not trained.")
        resume_vector = self.vectorizer.transform([" ".join(resume_terms)])
        return self.model.predict_proba(resume_vector)[0][1]

class TalentScreeningSystem:
    def __init__(self, parser: ResumeParser, evaluator: EvaluationModel):
        self.parser = parser
        self.evaluator = evaluator

    def score_resumes(self, resumes: List[str]) -> Dict[str, float]:
        scores = {}
        for idx, resume in enumerate(resumes):
            terms = self.parser.parse(resume)
            score = self.evaluator.evaluate(terms)
            scores[f'resume_{idx}'] = score
        return scores

# Example Usage
if __name__ == "__main__":
    resumes = [
        "Alice has a PhD in Computer Science and 10 years of experience in AI.",
        "Bob is a junior developer with a focus on web technologies."
    ]

    labels = [1, 0]  # Assuming binary classification for simplicity

    parser = ResumeParser()

    evaluator = EvaluationModel()
    evaluator.train([parser.parse(resume) for resume in resumes], labels)

    screening_system = TalentScreeningSystem(parser, evaluator)
    scores = screening_system.score_resumes(resumes)
    print(json.dumps(scores, indent=2))

