    global _call_count, _last_reset
    if time.time() - _last_reset > 60:
        _call_count = 0
        _last_reset = time.time()
    _call_count += 1
    if _call_count > MAX_CALLS_PER_MINUTE:
        raise RuntimeError("Rate limit exceeded")

