    def execute(self, tools, inputs):
        review_tool = tools.get("ContentReviewerX")

        feedback = review_tool.review(inputs)

        return feedback


class RenewableEnergyProject(MultiAgentSystem):
    def __init__(self):
        super().__init__(

            roles=[Researcher(), Writer(), Reviewer()],
            tools={
                "SearchToolV4": SearchToolV4(),
                "DataAnalyzerV5": DataAnalyzerV5(),
                "ReportGeneratorPro": ReportGeneratorPro(),

                "ContentReviewerX": ContentReviewerX()
            }
        )


    def workflow(self):

        research_insights = self.roles[0].execute(self.tools)
        draft_report = self.roles[1].execute(self.tools, research_insights)
        review_feedback = self.roles[2].execute(self.tools, draft_report)
        return review_feedback

