import openai
from dataclasses import dataclass

from typing import List, Dict, Any

@dataclass
class Applicant:
    identifier: str
    financial_history: List[Dict[str, Any]]
    requested_amount: float

class ScoringAgent:
    def __init__(self, api_key: str):
        openai.api_key = api_key
        self.model_name = "gpt-4.0-finance"


    def assess_credit(self, applicant: Applicant) -> str:
        input_data = self._prepare_input(applicant)
        result = openai.Completion.create(
            engine=self.model_name,
            prompt=input_data,
            max_tokens=150,
            temperature=0.2
        )
        return result.choices[0].text.strip()

    def _prepare_input(self, applicant: Applicant) -> str:
        financial_records = "; ".join(f"{record['date']}: {record['activity']}" for record in applicant.financial_history)
        return (f"Assess the credit risk for applicant {applicant.identifier}. "
                f"Financial history: {financial_records}. "
                f"Requested loan amount: {applicant.requested_amount}. "
                "Make a lending recommendation.")


def main():
    api_key = "your-openai-api-key"
    agent = ScoringAgent(api_key)



    applicant_data = Applicant(
        identifier="A12345",
        financial_history=[
            {"date": "2023-01-15", "activity": "Salary payment received: $5000"},

            {"date": "2023-02-10", "activity": "Credit card payment: $1500"},
            {"date": "2023-03-05", "activity": "Loan repayment: $200"}
        ],
        requested_amount=10000.0
    )


    recommendation = agent.assess_credit(applicant_data)
    print(f"Lending Recommendation for {applicant_data.identifier}: {recommendation}")


if __name__ == "__main__":
    main()

