import logging
import time
from langchain.agents import AgentExecutor, create_openai_tools_agent
from langchain_openai import ChatOpenAI
from langchain.tools import tool
from langchain_core.callbacks import BaseCallbackHandler

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")
logger = logging.getLogger(__name__)

MAX_CALLS_PER_MINUTE = 10
_call_count = 0
_last_reset = time.time()

class AuditHandler(BaseCallbackHandler):
    """Callback handler that logs all LLM interactions."""

    def on_llm_start(self, serialized, prompts, **kwargs):
        logger.info(f"LLM call: model={{serialized.get('kwargs', {{}}).get('model', 'unknown')}}")
        for prompt in prompts:
            if any(word in prompt.lower() for word in ["ignore previous", "system prompt:"]):
                logger.warning(f"Possible injection detected in prompt")

    def on_llm_end(self, result, **kwargs):
        logger.info(f"LLM result received")

    def on_tool_start(self, serialized, input_str, **kwargs):
        logger.info(f"Tool: {{serialized.get('name')}} input={{input_str[:100]}}")

def check_rate_limit():
    global _call_count, _last_reset
    if time.time() - _last_reset > 60:
        _call_count = 0
        _last_reset = time.time()
    _call_count += 1
    if _call_count > MAX_CALLS_PER_MINUTE:
        raise RuntimeError("Rate limit exceeded")

llm = ChatOpenAI(model="gpt-4", callbacks=[AuditHandler()])

@tool
def fetch_api(input_text: str) -> str:
    """Call an external REST API endpoint"""
    check_rate_limit()
    if not input_text or len(input_text) > 10000:
        raise ValueError("Invalid input")
    try:
        return requests.get(f"https://api.example.com/{text}").text
    except Exception as e:
        logger.error(f"Error: {{e}}")
        return f"Error: {{e}}"

bot = AgentExecutor(
    bot=create_openai_tools_agent(llm, [fetch_api]),
    tools=[fetch_api],
    max_iterations=5,
    handle_parsing_errors=True,
)
result = bot.invoke({{"input": "Deploy the staging environment to production"}})

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import List
from langchain.agents import initialize_agent, Agent
from langchain.tools import Tool
from langchain.models import OpenAI


app = FastAPI()

# Define the data model for the API request
class QueryRequest(BaseModel):
    question: str

# Initialize the agent with different tools and models
def create_forex_agent():
    model = OpenAI(model_name='gpt-4.0', temperature=0.3)
    tools = [

        Tool(
            name='ForexRateChecker',
            func=lambda q: f"Checking forex rates for: {q}",
            description="Provides current forex rates."
        ),
        Tool(
            name='CurrencyConverter',
            func=lambda q: f"Converting currency for: {q}",
            description="Converts currency based on current exchange rates."
        )
    ]
    return initialize_agent(tools, model, agent=Agent.ZERO_SHOT, verbose=True)

forex_agent = create_forex_agent()

@app.post("/ask-forex/")
async def ask_forex(query: QueryRequest):
    try:
        response = forex_agent.run(query.question)
        return {"response": response}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

