from crewai import CrewAI, Agent

class ResearcherAgent(Agent):
    def setup(self):
        self.role_name = "Researcher"
        self.task_description = "Investigate the latest trends in renewable energy technology and compile detailed notes."
        self.tools = ["DataGatherer-v2.1", "TrendAnalyzer-v3.0"]

    def execute_task(self):
        data = self.use_tool("DataGatherer-v2.1", query="renewable energy trends 2023")
        trends = self.use_tool("TrendAnalyzer-v3.0", data=data)
        return trends

class WriterAgent(Agent):
    def setup(self):
        self.role_name = "Writer"
        self.task_description = "Draft an article based on the research notes provided by the Researcher."
        self.tools = ["DraftBot-v1.5", "GrammarFixer-v2.0"]

    def execute_task(self, research_notes):
        draft = self.use_tool("DraftBot-v1.5", notes=research_notes)
        polished_article = self.use_tool("GrammarFixer-v2.0", text=draft)
        return polished_article

class ReviewerAgent(Agent):

    def setup(self):
        self.role_name = "Reviewer"
        self.task_description = "Review the article for accuracy and coherence, suggesting improvements if necessary."
        self.tools = ["ContentChecker-v2.2", "FeedbackGenerator-v1.3"]

    def execute_task(self, article):
        errors = self.use_tool("ContentChecker-v2.2", text=article)
        if errors:
            suggestions = self.use_tool("FeedbackGenerator-v1.3", issues=errors)
            return suggestions
        return "The article is ready for publication."

class RenewableEnergyProject(CrewAI):
    def setup_agents(self):
        self.add_agent(ResearcherAgent())
        self.add_agent(WriterAgent())
        self.add_agent(ReviewerAgent())

    def run(self):
        research_notes = self.get_agent("Researcher").execute_task()
        article = self.get_agent("Writer").execute_task(research_notes)
        review_feedback = self.get_agent("Reviewer").execute_task(article)
        return review_feedback

if __name__ == "__main__":
    project = RenewableEnergyProject()
    final_feedback = project.run()
    print(final_feedback)

