import asyncio
import logging
import json
import os
from datetime import datetime
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,
    PermissionResultAllow, PermissionResultDeny,
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
os.makedirs("./audit", exist_ok=True)

DANGEROUS_COMMANDS = ["rm -rf", "sudo", "chmod 777", "mkfs"]

async def block_dangerous_bash(input_data, tool_use_id, context):
    """Block dangerous bash commands."""

    if input_data.get("tool_name") == "Bash":
        cmd = input_data.get("tool_input", {{}}).get("command", "")
        for pattern in DANGEROUS_COMMANDS:
            if pattern in cmd:
                logger.warning(f"Blocked dangerous command: {{cmd}}")
                return {{
                    "hookSpecificOutput": {{
                        "hookEventName": "PreToolUse",
                        "permissionDecision": "deny",

                        "permissionDecisionReason": f"Dangerous: {{pattern}}",
                    }}
                }}
    return {{}}

async def audit_log(input_data, tool_use_id, context):

    """Log every tool result to audit directory."""
    record = {{
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "tool": input_data.get("tool_name"),
        "tool_use_id": tool_use_id,
    }}
    fname = f"./audit/{{tool_use_id or 'unknown'}}.json"
    with open(fname, "w") as f:
        json.dump(record, f)

    return {{}}

async def permission_handler(tool_name, input_data, context):
    """Risk-based permission processor."""
    if tool_name == "Bash":
        cmd = input_data.get("command", "")
        if any(p in cmd for p in DANGEROUS_COMMANDS):
            return PermissionResultDeny(message="Blocked by policy")
    return PermissionResultAllow(updated_input=input_data)

async def main():
    options = ClaudeAgentOptions(
        allowed_tools=["Read", "Write", "Bash"],
        can_use_tool=permission_handler,
        max_turns=10,
        hooks={{
            "PreToolUse": [
                HookMatcher(matcher="Bash", hooks=[block_dangerous_bash]),
            ],
            "PostToolUse": [HookMatcher(hooks=[audit_log])],
        }},
    )
    async with ClaudeSDKClient(options=options) as client:
        await client.query("What is our refund policy?")
        async for message in client.receive_response():
            print(message)

asyncio.run(main())

import autogen
from autogen import Agent, ToolRegistry, action

# Define tools for analysis
@action
def data_loader(file_path):
    import pandas as pd
    try:
        return pd.read_csv(file_path)
    except Exception as e:
        return str(e)

@action
def statistical_analysis(dataframe, analysis_type='summary'):
    try:
        if analysis_type == 'summary':
            return dataframe.describe()
        elif analysis_type == 'correlation':
            return dataframe.corr()
        else:
            return "Analysis type not recognized"
    except Exception as e:
        return str(e)

@action
def visualize_data(dataframe, column):
    import matplotlib.pyplot as plt
    try:
        plt.figure(figsize=(10, 6))
        dataframe[column].hist(bins=20)
        plt.title(f'Distribution of {column}')
        plt.xlabel(column)
        plt.ylabel('Frequency')
        plt.grid(False)
        plt.savefig('/tmp/plot.png')
        return '/tmp/plot.png'
    except Exception as e:
        return str(e)

# Register tools
ToolRegistry.register_tool('data_loader_v2', data_loader)
ToolRegistry.register_tool('stat_analysis_v2', statistical_analysis)
ToolRegistry.register_tool('data_visualizer_v2', visualize_data)

# Define agents
class DataAssistant(Agent):
    def __init__(self):
        super().__init__(name='DataAssistant')

    def process_request(self, request):
        response = self.execute_tool(request['tool_name'], *request['params'])
        return response

class UserProxy(Agent):
    def __init__(self):
        super().__init__(name='UserProxy')

    def request_analysis(self, file_path, column_to_visualize):
        data_response = self.send_message('DataAssistant', {
            'tool_name': 'data_loader_v2',
            'params': [file_path]
        })

        analysis_response = self.send_message('DataAssistant', {
            'tool_name': 'stat_analysis_v2',
            'params': [data_response, 'summary']
        })

        visualize_response = self.send_message('DataAssistant', {
            'tool_name': 'data_visualizer_v2',
            'params': [data_response, column_to_visualize]
        })

        return analysis_response, visualize_response

# Instantiate agents
assistant = DataAssistant()
user_proxy = UserProxy()

# Simulate collaboration
file_path = '/path/to/sales_data.csv'
column_to_visualize = 'Total_Sales'

summary, plot_path = user_proxy.request_analysis(file_path, column_to_visualize)

print("Statistical Summary:")
print(summary)
print(f"Plot saved at: {plot_path}")

