weightings = {'Python': 2.0, 'Machine Learning': 3.0, 'API': 1.0, 'Data Analysis': 1.5}
analyzer = ResumeAnalyzer(keywords, weightings)
scorer = CandidateScorer('v1.0.0', analyzer)

