class CrewAI:
    def __init__(self, tools):

        self.tools = tools
        self.trust_system = AirCrewaiTrust()

    def perform_operation(self, operation_name, **kwargs):
        if not self.trust_system.is_operation_compliant(operation_name):
            raise PermissionError(f"Operation {operation_name} is not compliant with trust policies.")
        tool = self.tools.get(operation_name)
        if not tool:
            raise ValueError(f"No tool available for operation {operation_name}.")
        return tool.execute(**kwargs)

class AirCrewaiTrust:
    def __init__(self):
        self.compliant_operations = set()


    def is_operation_compliant(self, operation_name):
        return operation_name in self.compliant_operations


    def register_compliant_operation(self, operation_name):
        self.compliant_operations.add(operation_name)

class MaintenanceTool:
    def execute(self, **kwargs):
        return f"Executing maintenance with parameters: {kwargs}"

