class OrderChecker(Tool):
    def run(self, order_id):
        # Simulate checking the order status from a database
        mock_database = {
            '12345': 'shipped',
            '67890': 'processing',
            '11121': 'delivered'
        }
        return mock_database.get(order_id, 'order not found')

class RefundProcessor(Tool):
    def run(self, order_id, amount):
        # Simulate processing a refund
        return f'Refund of {amount} for order {order_id} has been successfully processed.'

class RecordUpdater(Tool):
    def run(self, order_id, status):
        # Simulate updating the order record
        return f'Order {order_id} status updated to {status}.'

class CustomerSupportAgent(Agent):
    def __init__(self):
        super().__init__(model='gpt-4.5-turbo')
        self.register_tool('check_order', OrderChecker())
        self.register_tool('process_refund', RefundProcessor())
        self.register_tool('update_record', RecordUpdater())

    def handle_request(self, query):
        if 'check order' in query:
            order_id = query.split()[-1]
            return self.call_tool('check_order', order_id=order_id)
        elif 'process refund' in query:
            parts = query.split()
            order_id = parts[-2]
            amount = parts[-1]
