from air_rag_trust import ProvenanceTracker, WriteGate, DriftDetector
from transformers import pipeline, AutoModelForSeq2SeqLM, AutoTokenizer

class LegalDocumentQASystem:
    def __init__(self):
        # Load QA model
        model_name = "legalbert/qa-legal-v2"
        self.tokenizer = AutoTokenizer.from_pretrained(model_name)
        self.qa_model = AutoModelForSeq2SeqLM.from_pretrained(model_name)

        # RAG pipeline components
        self.provenance_tool = ProvenanceTracker()
        self.write_guard = WriteGate(allow_sources=['trusted_legal_database.com', 'official-law-repo.org'])
        self.drift_watcher = DriftDetector(reference_dataset='legal_references_v1')

        # QA Pipeline
        self.qa_pipeline = pipeline(
            "question-answering",
            model=self.qa_model,
            tokenizer=self.tokenizer
        )

    def validate_source(self, metadata):
        return self.write_guard.is_source_allowed(metadata['source'])

    def track_provenance(self, inputs, outputs):
        self.provenance_tool.log(inputs, outputs)

    def detect_drift(self, legal_text):
        return self.drift_watcher.check_drift(legal_text)

    def answer_question(self, query, context, source_meta):
        if not self.validate_source(source_meta):
            raise PermissionError("Source not allowed by WriteGate.")

        drift_status = self.detect_drift(context)
        if drift_status:
            raise ValueError("Drift detected in the legal context.")

        inputs = {"question": query, "context": context}
        answer = self.qa_pipeline(inputs)
        self.track_provenance(inputs, answer)

        return answer['answer']

