from airragtrust.provenance import TraceabilityTracker
from airragtrust.gate import DocumentGate
from airragtrust.drift import ChangeMonitor
from transformers import BertForQuestionAnswering, BertTokenizer
from typing import List, Dict

class LegalDocQA:
    def __init__(self, model_name: str, version: str):
        self.tokenizer = BertTokenizer.from_pretrained(model_name)
        self.model = BertForQuestionAnswering.from_pretrained(model_name)
        self.tracker = TraceabilityTracker()
        self.gate = DocumentGate(allowlist_sources=['trusted_legal_db'])
        self.drift_monitor = ChangeMonitor(model_version=version)

    def check_compliance(self, document: str) -> bool:
        return self.gate.is_allowed(document)

    def track_provenance(self, doc_id: str, source: str) -> None:
        self.tracker.record_provenance(doc_id=doc_id, source=source)

    def monitor_drift(self, input_data: Dict) -> bool:
        return self.drift_monitor.has_drifted(input_data)

    def answer_question(self, question: str, legal_text: str) -> str:
        if not self.check_compliance(legal_text):
            raise ValueError("Source document is not on the allowlist.")

        inputs = self.tokenizer.encode_plus(question, legal_text, add_special_tokens=True, return_tensors="pt")
        answer_start_scores, answer_end_scores = self.model(**inputs, return_dict=False)

        answer_start = answer_start_scores.argmax()
        answer_end = answer_end_scores.argmax() + 1
        answer = self.tokenizer.convert_tokens_to_string(self.tokenizer.convert_ids_to_tokens(inputs["input_ids"][0][answer_start:answer_end]))

        return answer

def perform_legal_qa(documents: List[Dict[str, str]], queries: List[str], context: str, model_version: str) -> List[str]:
    qa_system = LegalDocQA(model_name='bert-large-uncased-whole-word-masking-finetuned-squad', version=model_version)
    results = []

    for document in documents:
        qa_system.track_provenance(doc_id=document['id'], source=document['source'])
        for query in queries:
            if qa_system.monitor_drift(input_data={"context": context, "question": query}):
                continue
            try:
                answer = qa_system.answer_question(query, document['text'])
                results.append(answer)
            except ValueError as e:
                results.append(str(e))

    return results

# Example usage
legal_docs = [
    {"id": "doc1", "source": "trusted_legal_db", "text": "Legal text content related to contract law."},
    {"id": "doc2", "source": "untrusted_source", "text": "Sample legal text from unverified source."}
]

questions = ["What are the main points of contract law?", "What is the statute of limitations?"]

answer = perform_legal_qa(documents=legal_docs, queries=questions, context="contractual agreements", model_version="v3.1")
print(answer)

