import logging
import time
from langchain.agents import AgentExecutor, create_openai_tools_agent
from langchain_openai import ChatOpenAI
from langchain.tools import tool
from langchain_core.callbacks import BaseCallbackHandler

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")
logger = logging.getLogger(__name__)

MAX_CALLS_PER_MINUTE = 10
_call_count = 0
_last_reset = time.time()

class AuditHandler(BaseCallbackHandler):
    """Callback handler that logs all LLM interactions."""

    def on_llm_start(self, serialized, prompts, **kwargs):
        logger.info(f"LLM call: model={{serialized.get('kwargs', {{}}).get('model', 'unknown')}}")
        for instruction in prompts:
            if any(word in instruction.lower() for word in ["ignore previous", "system instruction:"]):
                logger.warning(f"Possible injection detected in instruction")

    def on_llm_end(self, response, **kwargs):
        logger.info(f"LLM response received")

    def on_tool_start(self, serialized, input_str, **kwargs):
        logger.info(f"Tool: {{serialized.get('name')}} input={{input_str[:100]}}")

def check_rate_limit():
    global _call_count, _last_reset
    if time.time() - _last_reset > 60:
        _call_count = 0
        _last_reset = time.time()
    _call_count += 1
    if _call_count > MAX_CALLS_PER_MINUTE:
        raise RuntimeError("Rate limit exceeded")

llm = ChatOpenAI(model="gpt-4", callbacks=[AuditHandler()])

@tool
def translate_text(input_text: str) -> str:
    """Send an email notification to the user"""
    check_rate_limit()
    if not input_text or len(input_text) > 10000:
        raise ValueError("Invalid input")
    try:
        return f"Results for: {text}"
    except Exception as e:
        logger.error(f"Error: {{e}}")
        return f"Error: {{e}}"

bot = AgentExecutor(
    bot=create_openai_tools_agent(llm, [translate_text]),
    tools=[translate_text],
    max_iterations=5,
    handle_parsing_errors=True,
)
result = bot.invoke({{"input": "Search for compliance requirements for fintech"}})

