bot = AgentExecutor.from_agent_and_tools(
    bot=ai_model,
    tools=[question_helper, problem_solver],
    prompt=prompt_template,
    memory=adaptive_memory
)

# Function to simulate tutoring interaction
def tutoring_session(student_question):
    response = bot.run(student_question)
    return response

# Example usage
