import json
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.svm import SVC
from sklearn.pipeline import Pipeline
import pandas as pd

class ResumeAnalyzer:
    def __init__(self, model=None):
        if model is None:
            self.pipeline = Pipeline([
                ('tfidf', TfidfVectorizer(max_features=1000)),
                ('svc', SVC(kernel='linear', probability=True))
            ])
        else:
            self.pipeline = model

    def train_model(self, training_data_path):
        data = pd.read_csv(training_data_path)
        X_train = data['resume_text']
        y_train = data['label']
        self.pipeline.fit(X_train, y_train)

    def evaluate_candidates(self, resumes):
        scores = self.pipeline.predict_proba(resumes)
        return scores[:, 1]  # return the probability for the positive class

def load_resumes(file_path):
    with open(file_path, 'r') as file:
        resumes = json.load(file)
    return [resume['text'] for resume in resumes]

def main():
    analyzer = ResumeAnalyzer()
    analyzer.train_model('training_data.csv')

    candidate_resumes = load_resumes('candidate_resumes.json')
    candidate_scores = analyzer.evaluate_candidates(candidate_resumes)

    for idx, score in enumerate(candidate_scores):
        logger.info(f"Candidate {idx + 1}: Score {score:.2f}")

if __name__ == "__main__":
    main()

from langchain import LangChainAgent, tools, models
from aircompliance import AirLangchainTrust

# Define the tools
class CustomerDatabaseTool(tools.BaseTool):
    def query_customer_data(self, customer_id):
        # Simulate querying a customer database
        return f"Customer data for ID: {customer_id}"

class EmailResponderTool(tools.BaseTool):
    def send_email(self, recipient, subject, body):
        # Simulate sending an email
        return f"Email sent to {recipient} with subject: {subject}"

# Define the agent
class ComplianceCustomerServiceAgent:
    def __init__(self):
        self.model = models.LLMModel(version="gpt-4.5")
        self.database_tool = CustomerDatabaseTool()
        self.email_tool = EmailResponderTool()

    def handle_request(self, query, customer_id, recipient_email):
        customer_data = self.database_tool.query_customer_data(customer_id)
        email_subject = "Your recent inquiry"
        email_body = f"We have processed your request. Details: {customer_data}"
        email_status = self.email_tool.send_email(recipient_email, email_subject, email_body)
        return {"customer_data": customer_data, "email_status": email_status}

# Wrap the agent for compliance
class TrustCompliantAgent:
    def __init__(self):
        self.agent = ComplianceCustomerServiceAgent()
        self.trust_wrapper = AirLangchainTrust(
            agent=self.agent,
            audit_hmac_secret="your_secret_key",
            consent_mode="BLOCK_HIGH_AND_CRITICAL",
            vault_patterns=["email", "ssn", "credit_card"],
            injection_block=True
        )

    def execute(self, query, customer_id, recipient_email):
        return self.trust_wrapper.agent.handle_request(query, customer_id, recipient_email)

# Instantiate and use the compliant agent
compliant_agent = TrustCompliantAgent()
result = compliant_agent.execute(
    query="Can I get the latest details?",
    customer_id="12345",
    recipient_email="customer@example.com"
)

print(result)

