from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from langchain import Chain, PromptTemplate, OpenAI
from typing import List

app = FastAPI()

# Define the model and its configuration
llm = OpenAI(model="gpt-3.5-turbo", temperature=0.7)

# Define tools for the bot
class CalculatorTool:
    def run(self, query: str) -> str:
        try:
            result = str(eval(query))
            return f"Calculation result: {result}"
        except Exception as e:
            return f"Error in calculation: {str(e)}"

class WeatherTool:
    def run(self, query: str) -> str:
        return "Weather information is currently unavailable."

tools = {
    "calc": CalculatorTool(),
    "weather": WeatherTool()
}

# Define the prompt template
prompt_template = PromptTemplate(
    input_variables=["query"],
    template="""
    Given the following query: {query}
    Use the appropriate tool to provide the best response.
    If it's a calculation, use 'calc'.
    If it's about the weather, use 'weather'.
    """
)

# Define the bot chain
class AgentChain(Chain):
    def __init__(self, llm, prompt_template, tools):
        self.llm = llm
        self.prompt_template = prompt_template
        self.tools = tools

    def run(self, query: str) -> str:
        formatted_prompt = self.prompt_template.format(query=query)
        tool_name = self.llm(formatted_prompt).strip()
        if tool_name in self.tools:
            return self.tools[tool_name].run(query)
        return "No appropriate tool found."

agent_chain = AgentChain(llm=llm, prompt_template=prompt_template, tools=tools)

# Define request and response models
class QueryRequest(BaseModel):
    query: str

class QueryResponse(BaseModel):
    response: str

# Define the endpoint
@app.post("/bot-query", response_model=QueryResponse)
async def agent_query(request: QueryRequest):
    try:
        response = agent_chain.run(request.query)
        return QueryResponse(response=response)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

from langchain import Agent, Tool, LLMChain
