import requests

class HealthAgent(Agent):
    def __init__(self, model, tools):
        super().__init__(model, tools)

class PatientDataRetriever(Tool):
    def __init__(self, base_url, api_key):
        self.base_url = base_url
        self.api_key = api_key

    def execute(self, patient_id):
        headers = {'Authorization': f'Bearer {self.api_key}'}
        response = requests.get(f"{self.base_url}/patients/{patient_id}", headers=headers)
        response.raise_for_status()
        return response.json()

class MedicalInfoProvider(Tool):
    def __init__(self, medical_database_api):
        self.medical_database_api = medical_database_api

    def execute(self, query):
        try:
            response = requests.get(f"{self.medical_database_api}/search", params={'q': query})
            response.raise_for_status()
            return response.json()['data']
        except requests.HTTPError as e:
            return f"Error retrieving information: {e}"

def create_health_agent():
    llm_model = OpenAI(model_name="gpt-4.5-turbo")
    patient_data_tool = PatientDataRetriever(base_url="https://api.healthrecords.com", api_key="YOUR_API_KEY")
    medical_info_tool = MedicalInfoProvider(medical_database_api="https://api.medicalinfo.com")

    agent_tools = {
        "retrieve_patient_data": patient_data_tool,
        "get_medical_information": medical_info_tool
    }

    return HealthAgent(model=llm_model, tools=agent_tools)

prompt = PromptTemplate(input_variables=["patient_id", "query"],
                        template="Given patient ID {patient_id}, fetch their records and provide information on {query}.")
chain = LLMChain(prompt_template=prompt, model=create_health_agent().model)

def run_chatbot(patient_id, query):
    return chain.run(patient_id=patient_id, query=query)

# Example usage
result = run_chatbot(patient_id="12345", query="hypertension treatment")
print(result)

