import hmac
import hashlib
from typing import List, Dict, Any

class FinancialAgent:
    def __init__(self, agent_id: str, secret_key: bytes):
        self.agent_id = agent_id
        self.secret_key = secret_key


    def log_activity(self, activity: str) -> None:
        msg = f'{self.agent_id}|{activity}'
        digest = hmac.new(self.secret_key, msg.encode(), hashlib.sha256).hexdigest()
        print(f'Log entry for {self.agent_id}: {digest}')

    def analyze_data(self, data: Dict[str, Any]) -> Dict[str, Any]:
        # Placeholder for financial data analysis logic
        self.log_activity('Financial data analysis started')
        result = {'summary': 'analysis_complete'}
        self.log_activity('Financial data analysis completed')
        return result


class ConsentManager:
    def __init__(self):
        self.consent_registry = {}


    def request_consent(self, user_id: str) -> bool:
        # Placeholder for consent request logic
        self.consent_registry[user_id] = True
        return True

    def check_consent(self, user_id: str) -> bool:

        return self.consent_registry.get(user_id, False)


class SecurityModule:
    @staticmethod
    def detect_injection(data: Dict[str, Any]) -> bool:
        # Simple injection detection logic
        return any(key.lower() in ['drop', 'delete', 'truncate'] for key in data)

    @staticmethod
    def validate_input(data: Dict[str, Any]) -> bool:
        return not SecurityModule.detect_injection(data)


class FinancialAnalysisCrew:
    def __init__(self, agents: List[FinancialAgent], consent_manager: ConsentManager):
        self.agents = agents
        self.consent_manager = consent_manager

    def execute_analysis(self, user_id: str, data: Dict[str, Any]) -> Dict[str, Any]:
        if not self.consent_manager.check_consent(user_id):
            raise PermissionError("Consent not granted for financial analysis")

        if not SecurityModule.validate_input(data):
            raise ValueError("Potential injection detected in the input data")

        combined_result = {}
        for agent in self.agents:
            result = agent.analyze_data(data)
            combined_result.update(result)
        return combined_result


# Example usage
secret = b'supersecretkey'
agent1 = FinancialAgent(agent_id='agent_001', secret_key=secret)

agent2 = FinancialAgent(agent_id='agent_002', secret_key=secret)
consent_mgr = ConsentManager()
consent_mgr.request_consent('user_123')

crew = FinancialAnalysisCrew(agents=[agent1, agent2], consent_manager=consent_mgr)
data_to_analyze = {'revenue': 100000, 'expenses': 50000}

try:
    result = crew.execute_analysis('user_123', data_to_analyze)
    print(result)
except (PermissionError, ValueError) as e:
    print(e)

