    def perform_task(self, data_insights):
        print(f"{self.name}: Creating content based on data insights.")
        sleep(random.uniform(1.0, 2.0))

        return f"Article draft based on insights: {data_insights['insights']}"

class QualityAssessor(Agent):
    def __init__(self):
        super().__init__("QualityAssessor")


    def perform_task(self, draft):
        print(f"{self.name}: Reviewing and providing feedback on the draft.")
        sleep(random.uniform(0.5, 1.0))
        feedback = "Review notes added to the draft."

        return f"{draft}\n{feedback}"

def conduct_research_task():
    data_analyst = DataAnalyst()
    content_creator = ContentCreator()
    quality_assessor = QualityAssessor()

    with ThreadPoolExecutor(max_workers=3) as executor:

        data_future = executor.submit(data_analyst.perform_task)
        data_insights = data_future.result()

        content_future = executor.submit(content_creator.perform_task, data_insights)
        draft = content_future.result()

        review_future = executor.submit(quality_assessor.perform_task, draft)
        final_document = review_future.result()

    print("Final Document:\n", final_document)


if __name__ == "__main__":
    conduct_research_task()

