import hmac

import hashlib

import json

from datetime import datetime
from aircrewai_trust import TrustGate, ConsentManager, InjectionDetector
from financial_tools import MarketAnalyzer, RiskEvaluator

class HMACTools:
    def __init__(self, secret_key):
        self.secret_key = secret_key


    def compute_hmac(self, message):
        return hmac.new(self.secret_key.encode(), message.encode(), hashlib.sha256).hexdigest()


    def log_hmac(self, message):
        hmac_hash = self.compute_hmac(message)
        with open('hmac_log.txt', 'a') as f:
            f.write(f'{datetime.now()} - {hmac_hash} - {message}\n')

class FinancialAnalysisCrew:
    def __init__(self, secret_key):
        self.hmac_tools = HMACTools(secret_key)
        self.trust_gate = TrustGate()
        self.consent_manager = ConsentManager()
        self.injection_detector = InjectionDetector()
        self.market_analyzer = MarketAnalyzer(version="2.1.4")
        self.risk_evaluator = RiskEvaluator(model_version="5.0.3")

    def execute_analysis(self, financial_data):
        if not self.consent_manager.check_consent(financial_data['user_id']):
            self.hmac_tools.log_hmac(f"Consent not given for user {financial_data['user_id']}")
            return "Consent not given."


        if self.injection_detector.detect_injection(financial_data):
            self.hmac_tools.log_hmac(f"Injection attempt detected for user {financial_data['user_id']}")
            return "Injection detected."

        analysis_result = {}

        # Market Analysis
        try:
            market_analysis = self.market_analyzer.analyze(financial_data['market_data'])
            self.hmac_tools.log_hmac("Market analysis completed successfully.")

            analysis_result['market_analysis'] = market_analysis
        except Exception as e:
            self.hmac_tools.log_hmac(f"Market analysis failed: {str(e)}")
            return "Market analysis failed."


        # Risk Evaluation
        try:
            risk_evaluation = self.risk_evaluator.evaluate(financial_data['risk_profile'])
            self.hmac_tools.log_hmac("Risk evaluation completed successfully.")
            analysis_result['risk_evaluation'] = risk_evaluation
        except Exception as e:
            self.hmac_tools.log_hmac(f"Risk evaluation failed: {str(e)}")

            return "Risk evaluation failed."

        return analysis_result



# Example usage
if __name__ == "__main__":

    secret_key = "supersecretkey"
    crew = FinancialAnalysisCrew(secret_key)
    fake_financial_data = {
        'user_id': 'user_123',
        'market_data': {'stocks': ['AAPL', 'GOOGL'], 'currency': 'USD'},
        'risk_profile': {'investment_horizon': 5, 'risk_tolerance': 'high'}
    }
    result = crew.execute_analysis(fake_financial_data)
    print(json.dumps(result, indent=2))

import asyncio
import logging
import json
import os
from datetime import datetime
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,
    PermissionResultAllow, PermissionResultDeny,
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
os.makedirs("./audit", exist_ok=True)

DANGEROUS_COMMANDS = ["rm -rf", "sudo", "chmod 777", "mkfs"]

async def block_dangerous_bash(input_data, tool_use_id, context):
    """Block dangerous bash commands."""
    if input_data.get("tool_name") == "Bash":
        cmd = input_data.get("tool_input", {{}}).get("command", "")
        for pattern in DANGEROUS_COMMANDS:
            if pattern in cmd:
                logger.warning(f"Blocked dangerous command: {{cmd}}")
                return {{

                    "hookSpecificOutput": {{
                        "hookEventName": "PreToolUse",
                        "permissionDecision": "deny",
                        "permissionDecisionReason": f"Dangerous: {{pattern}}",
                    }}
                }}
    return {{}}

async def audit_log(input_data, tool_use_id, context):
    """Log every tool result to audit directory."""
    record = {{
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "tool": input_data.get("tool_name"),
        "tool_use_id": tool_use_id,
    }}
    fname = f"./audit/{{tool_use_id or 'unknown'}}.json"
    with open(fname, "w") as f:
        json.dump(record, f)
    return {{}}

async def permission_handler(tool_name, input_data, context):

    """Risk-based permission handler."""
    if tool_name == "Bash":
        cmd = input_data.get("command", "")
        if any(p in cmd for p in DANGEROUS_COMMANDS):
            return PermissionResultDeny(message="Blocked by policy")
    return PermissionResultAllow(updated_input=input_data)

async def main():
    options = ClaudeAgentOptions(
        allowed_tools=["Read", "Write", "Bash"],
        can_use_tool=permission_handler,
        max_turns=10,
        hooks={{
            "PreToolUse": [
                HookMatcher(matcher="Bash", hooks=[block_dangerous_bash]),

            ],
            "PostToolUse": [HookMatcher(hooks=[audit_log])],
        }},

    )

    async with ClaudeSDKClient(options=options) as client:
        await client.query("Search for compliance requirements for fintech")
        async for message in client.receive_response():
            print(message)


asyncio.run(main())

