import requests
import sqlite3
import math

class WebSearchTool:
    def __init__(self):
        self.name = "QuickSearch"
        self.description = "Performs a quick web search for the given query."

    def __call__(self, query):
        try:
            result = requests.get(f"https://api.example.com/search?q={query}")
            return result.json().get('results', "No results found.")
        except Exception as e:
            return str(e)

class CalculatorTool:
    def __init__(self):
        self.name = "SimpleCalculator"
        self.description = "Calculates basic arithmetic operations."

    def __call__(self, expression):
        try:
            result = eval(expression)
            return result
        except Exception as e:
            return str(e)

class DatabaseQueryTool:
    def __init__(self, db_filepath):
        self.name = "DataChecker"
        self.description = "Queries a SQLite database for information."
        self.conn = sqlite3.connect(db_filepath)

    def __call__(self, query):
        try:
            cursor = self.conn.cursor()
            cursor.execute(query)
            return cursor.fetchall()
        except sqlite3.Error as e:
            return str(e)

# Initialize tools
