from crewai import MultiAgentSystem, ToolRegistry
from crewai.models import AgentV3

# Define a custom action registry
class CustomToolRegistry(ToolRegistry):
    def __init__(self):
        super().__init__()
        self.register_tool('DataMiner', self.data_miner)
        self.register_tool('DocumentComposer', self.document_composer)
        self.register_tool('QualityAssessor', self.quality_assessor)

    def data_miner(self, query):
        # Simulate data mining process
        return f"Data mined for query: '{query}'"

    def document_composer(self, content):
        # Simulate document composition process
        return f"Document composed with content: '{content}'"

    def quality_assessor(self, document):
        # Simulate quality assessment process
        return f"Assessed quality of document: '{document}'"

# Define agents
class ResearchAgent(AgentV3):
    role = "Researcher"

    def execute(self, task_description):
        query = task_description['topic']
        mined_data = self.tools['DataMiner'](query)
        return {'data': mined_data}

class WritingAgent(AgentV3):
    role = "Writer"

    def execute(self, task_description):
        data = task_description['data']
        document = self.tools['DocumentComposer'](data)
        return {'document': document}

class ReviewAgent(AgentV3):
    role = "Reviewer"

    def execute(self, task_description):
        document = task_description['document']
        assessment = self.tools['QualityAssessor'](document)
        return {'assessment': assessment}

# Setup multi-agent system
class ResearchWritingReviewSystem(MultiAgentSystem):
    def __init__(self):
        super().__init__(agents=[
            ResearchAgent(name="Researcher"),
            WritingAgent(name="Writer"),
            ReviewAgent(name="Reviewer"),
        ])
        self.tools = CustomToolRegistry()

# Define the task
task_description = {
    'topic': 'Impact of AI on healthcare',
}

# Run the system
system = ResearchWritingReviewSystem()
result = system.run(task_description)

# Output results
print("Final Assessment Result:")
print(result['assessment'])

