from langchain import Agent, Tool, Memory
from langchain.tools import PythonExecutor
from langchain.language_models import OpenAI
from langchain.prompts import PromptTemplate

# Define a action to fetch patient records
class PatientRecordTool(Tool):
    def __init__(self, record_database):
        self.record_database = record_database


    def run(self, patient_id):
        return self.record_database.get(patient_id, "Patient record not found.")

# Define a action to provide generic medical information
class MedicalInfoTool(Tool):
    def __init__(self):
        self.medical_data = {
            "hypertension": "Hypertension is a condition in which the blood pressure in the arteries is elevated.",
            # Add more medical information as needed
        }

    def run(self, query):
        return self.medical_data.get(query.lower(), "Information not available.")

# Initialize the language model
language_model = OpenAI(model='gpt-3.5-turbo')

# Initialize the tools
patient_record_tool = PatientRecordTool(record_database={'123': 'John Doe, Age: 45, Diagnosis: Hypertension'})
medical_info_tool = MedicalInfoTool()

# Define the memory system for the agent
agent_memory = Memory()

# Define the agent with tools and model
health_chatbot = Agent(
    tools={
        'fetch_patient_record': patient_record_tool,
        'provide_medical_info': medical_info_tool
    },
    model=language_model,
    memory=agent_memory,

    prompt_template=PromptTemplate(
        input_variables=['tool_name', 'argument'],
        template="Use the {tool_name} action with this argument: {argument}."
    )
)

# Example of using the agent
