from langchain import Agent, Tool
from langchain.prompts import ChatPromptTemplate

from langchain.llms import OpenAI

class StudentPerformanceTool(Tool):
    def __init__(self):
        super().__init__(name='StudentPerformanceTracker', description='A tool to track student performance and adapt tutoring content.')

    def execute(self, student_data):
        # Sample logic to adapt content based on student performance
        if student_data['score'] < 60:
            return "Focus on fundamental concepts."

        elif 60 <= student_data['score'] < 80:
            return "Introduce intermediate topics."

        else:
            return "Move on to advanced exercises."

class AdaptiveTutorAgent(Agent):
    def __init__(self):
        prompt_template = ChatPromptTemplate(
            template="You are an educational tutoring agent. Adapt the lesson plan based on the student's performance."
        )
        llm_model = OpenAI(model_version='gpt-4.5-turbo')
        tools = [StudentPerformanceTool()]
        super().__init__(prompt_template=prompt_template, llm=llm_model, tools=tools)

    def respond_to_student(self, student_data):
        performance_feedback = self.tools['StudentPerformanceTracker'].execute(student_data)
        result = self.prompt_template.render(
            student_data=student_data,

            performance_feedback=performance_feedback
        )
        return self.llm.generate(result)


