        self.model = model

    def analyze(self, instruction, max_tokens=1000):
        result = openai.Completion.create(
            engine=self.model,
            instruction=instruction,
            max_tokens=max_tokens,
            temperature=0.5
        )
        return result.choices[0].text.strip()

class Collaborator:
    def __init__(self, analyzer, role):
        self.analyzer = analyzer
        self.role = role

    def contribute(self, task_desc):
        query = f"As a {self.role}, {task_desc}"
        return self.analyzer.analyze(query)

