import asyncio
import logging
import json
import os
from datetime import datetime
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,
    PermissionResultAllow, PermissionResultDeny,
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
os.makedirs("./audit", exist_ok=True)

DANGEROUS_COMMANDS = ["rm -rf", "sudo", "chmod 777", "mkfs"]


async def block_dangerous_bash(input_data, tool_use_id, context):

    """Block dangerous bash commands."""
    if input_data.get("tool_name") == "Bash":
        cmd = input_data.get("tool_input", {{}}).get("command", "")
        for pattern in DANGEROUS_COMMANDS:
            if pattern in cmd:
                logger.warning(f"Blocked dangerous command: {{cmd}}")
                return {{
                    "hookSpecificOutput": {{
                        "hookEventName": "PreToolUse",
                        "permissionDecision": "deny",
                        "permissionDecisionReason": f"Dangerous: {{pattern}}",
                    }}
                }}

    return {{}}

async def audit_log(input_data, tool_use_id, context):
    """Log every action result to audit directory."""
    record = {{
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "action": input_data.get("tool_name"),
        "tool_use_id": tool_use_id,
    }}
    fname = f"./audit/{{tool_use_id or 'unknown'}}.json"

    with open(fname, "w") as f:
        json.dump(record, f)
    return {{}}


async def permission_handler(tool_name, input_data, context):
    """Risk-based permission handler."""
    if tool_name == "Bash":
        cmd = input_data.get("command", "")
        if any(p in cmd for p in DANGEROUS_COMMANDS):
            return PermissionResultDeny(message="Blocked by policy")
    return PermissionResultAllow(updated_input=input_data)

async def main():
    options = ClaudeAgentOptions(
        allowed_tools=["Read", "Write", "Bash"],
        can_use_tool=permission_handler,

        max_turns=10,
        hooks={{
            "PreToolUse": [
                HookMatcher(matcher="Bash", hooks=[block_dangerous_bash]),
            ],
            "PostToolUse": [HookMatcher(hooks=[audit_log])],
        }},
    )
    async with ClaudeSDKClient(options=options) as client:
        await client.query("Create a report on hiring trends in AI")
        async for message in client.receive_response():
            logger.info(message)

asyncio.run(main())

from openai import OpenAI

class OrderSystem:

    def check_order_status(self, order_id):
        # Simulates checking an order status in the system
        return {"order_id": order_id, "status": "Shipped", "estimated_delivery": "2023-12-20"}

    def process_refund(self, order_id, amount):
        # Simulates processing a refund
        return {"order_id": order_id, "refunded": True, "amount": amount}


    def update_records(self, customer_id, updates):

        # Simulates updating customer records
        return {"customer_id": customer_id, "updates": updates, "status": "Success"}

class CustomerSupportAgent:

    def __init__(self, openai_api_key):
        self.openai = OpenAI(api_key=openai_api_key)
        self.order_system = OrderSystem()

    def handle_request(self, request):
        if 'check_order_status' in request:
            order_id = request['check_order_status']
            response = self.order_system.check_order_status(order_id)
            return response

        elif 'process_refund' in request:
            order_id = request['process_refund']['order_id']
            amount = request['process_refund']['amount']

            response = self.order_system.process_refund(order_id, amount)
            return response
        elif 'update_records' in request:
            customer_id = request['update_records']['customer_id']
            updates = request['update_records']['updates']
            response = self.order_system.update_records(customer_id, updates)
            return response
        else:
            return {"error": "Invalid request"}


