        super().__init__(name)
        self.model_version = "WriteMaster v2.5"

    def perform_task(self, task):
        print(f"{self.name} using {self.model_version} is working on the writing task: {task.description}")


class ReviewerAgent(Agent):
    def __init__(self, name="Reviewer"):
        super().__init__(name)
        self.model_version = "ReviewBot v1.8"

    def perform_task(self, task):
        print(f"{self.name} using {self.model_version} is performing the review task: {task.description}")

