    tutoring_agent = AdaptiveEducationAgent()
    student_data = {
        "skill_level": "intermediate",
        "recent_performance": "struggled with algebra",
        "question": "What are the causes of the American Revolution?"
    }
    response = tutoring_agent.execute(student_data)
    print(response)

if __name__ == "__main__":
