import hmac
import hashlib
import json
from datetime import datetime
from AirCrewaiTrust import AircrewAgent, BlackboxCompliance, ConsentManager, InjectionDetector

class FinAnalysisAgent(AircrewAgent):
    def __init__(self, agent_id, secret_key):
        super().__init__(agent_id)
        self.secret_key = secret_key
        self.consent_manager = ConsentManager(agent_id)
        self.injection_detector = InjectionDetector()

    def log_hmac(self, message):
        timestamp = datetime.utcnow().isoformat()
        msg = f"{timestamp}:{message}"
        hmac_digest = hmac.new(self.secret_key.encode('utf-8'), msg.encode('utf-8'), hashlib.sha256).hexdigest()
        log_entry = {
            "timestamp": timestamp,
            "agent_id": self.agent_id,
            "message": message,
            "hmac": hmac_digest
        }
        with open(f"{self.agent_id}_logs.json", "a") as log_file:
            json.dump(log_entry, log_file)
            log_file.write("\n")

    def perform_analysis(self, data):
        if not self.consent_manager.check_consent(data['user_id']):
            raise PermissionError("User consent required for analysis.")

        if self.injection_detector.detect(data):
            raise ValueError("Potential injection detected in data.")

        # Dummy analysis logic
        result = {"summary": f"Processed {len(data['transactions'])} transactions."}
        self.log_hmac(f"Analysis performed on user {data['user_id']}")
        return result


