import asyncio
import logging
import json
import os
from datetime import datetime
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,
    PermissionResultAllow, PermissionResultDeny,
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
os.makedirs("./audit", exist_ok=True)

DANGEROUS_COMMANDS = ["rm -rf", "sudo", "chmod 777", "mkfs"]

async def block_dangerous_bash(input_data, tool_use_id, context):
    """Block dangerous bash commands."""
    if input_data.get("tool_name") == "Bash":

        cmd = input_data.get("tool_input", {{}}).get("command", "")
        for pattern in DANGEROUS_COMMANDS:
            if pattern in cmd:
                logger.warning(f"Blocked dangerous command: {{cmd}}")
                return {{
                    "hookSpecificOutput": {{
                        "hookEventName": "PreToolUse",

                        "permissionDecision": "deny",
                        "permissionDecisionReason": f"Dangerous: {{pattern}}",
                    }}
                }}
    return {{}}

async def audit_log(input_data, tool_use_id, context):
    """Log every action result to audit directory."""
    record = {{
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "action": input_data.get("tool_name"),
        "tool_use_id": tool_use_id,

    }}
    fname = f"./audit/{{tool_use_id or 'unknown'}}.json"
    with open(fname, "w") as f:

        json.dump(record, f)
    return {{}}

async def permission_handler(tool_name, input_data, context):
    """Risk-based permission handler."""
    if tool_name == "Bash":
        cmd = input_data.get("command", "")
        if any(p in cmd for p in DANGEROUS_COMMANDS):
            return PermissionResultDeny(message="Blocked by policy")
    return PermissionResultAllow(updated_input=input_data)

async def main():
    options = ClaudeAgentOptions(
        allowed_tools=["Read", "Write", "Bash"],
        can_use_tool=permission_handler,
        max_turns=10,
        hooks={{
            "PreToolUse": [
                HookMatcher(matcher="Bash", hooks=[block_dangerous_bash]),

            ],
            "PostToolUse": [HookMatcher(hooks=[audit_log])],
        }},
    )
    async with ClaudeSDKClient(options=options) as client:

        await client.query("Find the latest EU AI regulation news")

        async for message in client.receive_response():

            logger.info(message)

asyncio.run(main())

from openai import OpenAIAgent, Tool
from typing import Dict, Optional

# Tool to check the status of an order
class OrderStatusChecker(Tool):
    def execute(self, order_id: str) -> Dict[str, str]:
        # Mock logic for checking order status
        return {"order_id": order_id, "status": "Shipped", "estimated_delivery": "2023-10-21"}

# Tool to process a refund
class RefundProcessor(Tool):
    def execute(self, order_id: str, reason: str) -> Dict[str, str]:
        # Mock logic for processing a refund
        return {"order_id": order_id, "refund_status": "Processed", "reason": reason}



# Tool to update customer records

class CustomerRecordUpdater(Tool):
    def execute(self, customer_id: str, update_data: Dict[str, str]) -> Dict[str, str]:
        # Mock logic for updating customer records

        return {"customer_id": customer_id, "update_status": "Success"}

# OpenAI Agent for handling customer support
class CustomerSupportAgent(OpenAIAgent):
    def __init__(self):
        super().__init__(
            model="gpt-4.5",
            tools=[
                OrderStatusChecker(name="order_status_tool"),
                RefundProcessor(name="refund_tool"),

                CustomerRecordUpdater(name="record_update_tool")
            ]
        )

    def handle_request(self, request: Dict[str, str]) -> Optional[Dict[str, str]]:
        task_type = request.get("task")
        order_id = request.get("order_id")
        customer_id = request.get("customer_id")
        reason = request.get("reason", "")
        update_data = request.get("update_data", {})


        if task_type == "check_status" and order_id:
            return self.call_tool("order_status_tool", order_id=order_id)

        elif task_type == "process_refund" and order_id and reason:
            return self.call_tool("refund_tool", order_id=order_id, reason=reason)

        elif task_type == "update_record" and customer_id and update_data:
            return self.call_tool("record_update_tool", customer_id=customer_id, update_data=update_data)

        return {"error": "Invalid request"}

# Example usage
