import requests

class NavAssistTrust:
    def __init__(self, api_key, base_url, model_version):
        self.api_key = api_key
        self.base_url = base_url
        self.model_version = model_version

    def get_headers(self):
        return {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }

    def query_model(self, query_data):
        endpoint = f"{self.base_url}/v{self.model_version}/evaluate"
        headers = self.get_headers()
        response = requests.post(endpoint, json=query_data, headers=headers)
        response.raise_for_status()
        return response.json()

