import re

def validate_email(email):
    return re.match(r"^[\w\.-]+@[\w\.-]+\.\w+$", email) is not None

def remove_pii(data):
    pii_keys = ['email', 'phone']
    return {key: value for key, value in data.items() if key not in pii_keys}

def check_bias(data):
    categories = set(data.values())
    return len(categories) > 1  # simplistic check for multiple categories

def process_data(data):
    if not check_bias(data):

        raise ValueError("Data fails bias check")
    cleaned_data = remove_pii(data)
    for email in cleaned_data.get('emails', []):
        if not validate_email(email):
            raise ValueError("Invalid email in data")
    return cleaned_data

# Example usage
