from langchain import LangChainAgent
from langchain.prompts import BasePromptTemplate
from langchain.tools import Tool
from langchain.models import OpenAI
from langchain.chains import LLMChain

class AdaptiveTutoringAgent(LangChainAgent):
    def __init__(self):
        super().__init__()
        self.tools = [
            Tool(name="MathHelper", function=self.provide_math_help),
            Tool(name="ScienceExplainer", function=self.explain_science_concepts),
            Tool(name="HistoryGuide", function=self.guide_history_study)
        ]
        self.llm = OpenAI(model_name="gpt-4")
        self.adapt_chain = LLMChain(
            llm=self.llm,
            prompt=BasePromptTemplate.from_string(
                "Based on student's recent performance: {performance}, adapt tutoring strategy for {subject}."
            )
        )

    def provide_math_help(self, input_text: str) -> str:
        return f"Assisting with math: {input_text}"

    def explain_science_concepts(self, input_text: str) -> str:
        return f"Explaining science: {input_text}"

    def guide_history_study(self, input_text: str) -> str:
        return f"Guiding history study: {input_text}"

    def adapt_tutoring_strategy(self, performance_data: dict, subject: str) -> str:
        performance_summary = "; ".join(
            f"{key}: {value}" for key, value in performance_data.items()
        )
        return self.adapt_chain.run(performance=performance_summary, subject=subject)

    def decide_which_tool_to_use(self, query: str, performance_data: dict) -> str:
        subject = self.determine_subject(query)
        strategy = self.adapt_tutoring_strategy(performance_data, subject)
        return f"Chosen strategy for {subject}: {strategy}"

    def determine_subject(self, query: str) -> str:
        if "math" in query.lower():
            return "Math"
        elif "science" in query.lower():
            return "Science"
        elif "history" in query.lower():
            return "History"
        else:
            return "General"

# Example instantiation and usage:
agent = AdaptiveTutoringAgent()
student_performance = {
    "Math": "Improved",
    "Science": "Needs more practice",
    "History": "Consistent"
}
query = "Help me with math problems"
agent_response = agent.decide_which_tool_to_use(query, student_performance)
logger.info(agent_response)

