import hmac
import hashlib
import json
from datetime import datetime
from typing import Dict, Any

class ConsentManager:
    def __init__(self):
        self.consent_status = {}


    def request_consent(self, user_id: str) -> bool:
        # Simulate consent request, defaulting to granted
        self.consent_status[user_id] = True
        return self.consent_status[user_id]

    def has_consent(self, user_id: str) -> bool:
        return self.consent_status.get(user_id, False)

class LogManager:
    def __init__(self, secret_key: str):
        self.secret_key = secret_key

    def log_event(self, event_data: Dict[str, Any]) -> None:
        timestamp = datetime.utcnow().isoformat()
        event_data['timestamp'] = timestamp

        event_str = json.dumps(event_data, sort_keys=True)

        digest = hmac.new(self.secret_key.encode(), event_str.encode(), hashlib.sha256).hexdigest()

        # Simulate logging to external system

        logger.info(f"Logged Event: {event_str} with HMAC: {digest}")

class InjectionGuard:
    def detect_injection(self, user_input: str) -> bool:

        # Simple detection logic for demonstration purposes
        suspicious_patterns = ["DROP TABLE", "SELECT * FROM", "--"]
        for pattern in suspicious_patterns:
            if pattern in user_input:
                return True
        return False

class FinancialAnalysisAgent:
    def __init__(self, model_version: str, manager: LogManager, consent_mgr: ConsentManager, inj_guard: InjectionGuard):

        self.model_version = model_version
        self.manager = manager
        self.consent_mgr = consent_mgr
        self.inj_guard = inj_guard

    def analyze(self, data: str, user_id: str) -> str:
        if not self.consent_mgr.has_consent(user_id):
            return "Error: Consent not granted."

        if self.inj_guard.detect_injection(data):
            return "Error: Potential injection detected."

        # Simulated analysis
        result = f"Analysis Result for model {self.model_version}"

        # Logging the analysis event
        self.manager.log_event({
            "user_id": user_id,
            "model_version": self.model_version,
            "action": "analyze",
            "input_length": len(data),
            "result": result
        })


        return result

