import json

class AIModel:

    def __init__(self, model_name):
        self.model_name = model_name

    def query(self, input_text):
        response = openai.Completion.create(

            engine=self.model_name,
            prompt=input_text,
            max_tokens=100
        )
        self.record_log(input_text, response)
        return response

    def record_log(self, input_text, response):
        log_data = {
            'input': input_text,
            'output': response['choices'][0]['text'],
            'timestamp': time.time()
        }
        with open('audit_log.json', 'a') as logfile:
            logfile.write(json.dumps(log_data) + '\n')

