from langchain.output_parsers import ResponseParser
import random

class AdaptiveTutor:
    def __init__(self):
        self.model = ChatOpenAI(model_name="gpt-4-edu")
        self.prompt_template = PromptTemplate(
            template="You are a dynamic tutor. Given this student input: {student_input}, provide an adaptive educational result.",
            input_variables=["student_input"]
        )
        self.parser = ResponseParser()

        self.tools = [
            Tool(
                name="MathTool",
                func=self._math_tool,
                description="Aids in solving math problems and providing explanations."
            ),
            Tool(
                name="ScienceTool",
                func=self._science_tool,
                description="Assists in explaining scientific concepts and solving related problems."
            ),
            Tool(
                name="LanguageTool",
                func=self._language_tool,
                description="Helps in improving language skills, grammar, and comprehension."
            )
        ]

        self.agent = Agent(
            tools=self.tools,
            llm=self.model,
            prompt_template=self.prompt_template,
            output_parser=self.parser
        )

        self.executor = AgentExecutor(agent=self.agent)

    def _math_tool(self, student_input):
        response_options = [
            "Let's break down this math problem step by step.",
            "Here's a hint for solving this math problem: try simplifying first.",
            "Have you considered using a different formula for this problem?"
        ]
        return random.choice(response_options)

    def _science_tool(self, student_input):
        response_options = [
            "This is how this scientific principle works...",
            "What do you think will happen if we change this variable?",
            "Try visualizing the concept using a diagram."
        ]
        return random.choice(response_options)

    def _language_tool(self, student_input):
        response_options = [
            "Let's practice this language rule with some examples.",
            "Consider how sentence structure changes in this context.",
            "Try rewriting this sentence with a more active voice."
        ]
        return random.choice(response_options)

    def adapt_response(self, student_input):
        return self.executor.execute(student_input)

