from langchain.agents import Tool, AgentExecutor, Agent
from langchain.tools import FileReader, TextClassifier
from langchain.models import OpenAI

# Define a tool for reading and extracting content from documents
class DocumentExtractor(Tool):
    def __init__(self):
        super().__init__(name="document_extractor", description="Extract content from insurance claim documents.")

    def execute(self, file_path: str) -> str:
        with open(file_path, 'r') as file:
            return file.read()

# Define a tool for classifying the claim validity
class ClaimEvaluator(Tool):
    def __init__(self):
        super().__init__(name="claim_evaluator", description="Classify the validity of insurance claims.")
        self.classifier = TextClassifier("gpt-4-turbo")

    def execute(self, document_content: str) -> str:
        return self.classifier.classify(document_content)

# Instantiate tools
document_extractor = DocumentExtractor()
claim_evaluator = ClaimEvaluator()

# Initialize the agent with the defined tools
class ClaimsAgent(Agent):
    def __init__(self):
        super().__init__(tools=[document_extractor, claim_evaluator])

    def process_claim(self, file_path: str) -> str:
        document_content = self.run_tool("document_extractor", file_path)
        recommendation = self.run_tool("claim_evaluator", document_content)
        return recommendation

# Create an instance of the agent executor
claims_agent = ClaimsAgent()
claims_executive = AgentExecutor(agent=claims_agent)


# Example usage
file_path = "insurance_claim_2023.txt"
payout_recommendation = claims_executive.agent.process_claim(file_path)
print(f"Payout Recommendation: {payout_recommendation}")

